import { createClient } from "@supabase/supabase-js";
import * as dotenv from "dotenv";

dotenv.config();

async function verifyConnection() {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

  if (!supabaseUrl || !supabaseKey) {
    console.error("Γ¥î Error: NEXT_PUBLIC_SUPABASE_URL or NEXT_PUBLIC_SUPABASE_ANON_KEY is missing from .env");
    process.exit(1);
  }

  console.log(`≡ƒöù Attempting to connect to Supabase: ${supabaseUrl}`);

  const supabase = createClient(supabaseUrl, supabaseKey);

  try {
    // 1. Connection Ping (Select dummy)
    const { data: pingData, error: pingError } = await supabase.from("academic_years").select("count").limit(1);

    if (pingError) {
      console.error("Γ¥î Database Connection Failed:");
      console.error(pingError.message);
      process.exit(1);
    }

    console.log("Γ£à Database Connected Successfully!");

    // 2. Data Verification (Comprehensive Module Audit)
    const tablesToVerify = [
      "profiles", "academic_years", "school_settings", 
      "students", "teachers", "classes", "subjects", 
      "attendance", "marks", "exams", "fees", "payments"
    ];

    console.log("\n--- Module Readiness Audit ---");
    for (const table of tablesToVerify) {
      const { count, error } = await supabase.from(table).select("*", { count: 'exact', head: true });
      if (error) {
        console.warn(`Γ¥î Table '${table}': ERROR - ${error.message}`);
      } else {
        const status = (count !== null && count > 0) ? "Γ£à READY" : "ΓÜá∩╕Å EMPTY (Seed Required?)";
        console.log(`${status} Table '${table}': ${count} records found.`);
      }
    }

    console.log("\n≡ƒÜÇ All database checks passed! Data is accessible.");
  } catch (err) {
    console.error("Γ¥î Unexpected error during verification:");
    console.error(err);
    process.exit(1);
  }
}

verifyConnection();

