import { createClient } from "@/lib/supabase/server";
import { TimetableDashboard } from "@/components/timetable/TimetableDashboard";
import { getSessionRole } from "@/lib/auth-utils";

export default async function TimetablePage() {
  const supabase = await createClient();
  const role = await getSessionRole();
  const { data: { user } } = await supabase.auth.getUser();

  let timetables: any[] = [];
  let classes: any[] = [];
  let subjects: any[] = [];
  let teachers: any[] = [];
  const isStudent = role === "student";

  if (isStudent) {
    const { data: student } = await supabase
      .from("students")
      .select("*, class:classes(*)")
      .eq("profile_id", user?.id)
      .single();

    if (student) {
      const { data: classTimetables } = await supabase
        .from("timetables")
        .select(`
          *,
          class:classes(*),
          slots:timetable_slots(*, subject:subjects(*), teacher:teachers(*, profile:profiles(*)))
        `)
        .eq("class_id", student.class_id)
        .order("day_of_week");

      timetables = classTimetables || [];
      classes = student.class ? [student.class] : [];

      // Extract unique subjects and teachers from slots
      const subjectIds = new Set<string>();
      const teacherIds = new Set<string>();

      timetables.forEach(t => {
        t.slots?.forEach((s: any) => {
          if (s.subject_id) subjectIds.add(s.subject_id);
          if (s.teacher_id) teacherIds.add(s.teacher_id);
        });
      });

      if (subjectIds.size > 0) {
        const { data: classSubjects } = await supabase
          .from("subjects")
          .select("*")
          .in("id", Array.from(subjectIds));
        subjects = classSubjects || [];
      }

      if (teacherIds.size > 0) {
        const { data: classTeachers } = await supabase
          .from("teachers")
          .select("*, profile:profiles(*)")
          .in("id", Array.from(teacherIds));
        teachers = classTeachers || [];
      }
    }
  } else {
    // Admin/Teacher: All data
    const { data: allTimetables } = await supabase
      .from("timetables")
      .select(`
        *,
        class:classes(*),
        slots:timetable_slots(*, subject:subjects(*), teacher:teachers(*, profile:profiles(*)))
      `)
      .order("day_of_week");
    timetables = allTimetables || [];

    const { data: allClasses } = await supabase
      .from("classes")
      .select("*")
      .order("name");
    classes = allClasses || [];

    const { data: allSubjects } = await supabase
      .from("subjects")
      .select("*")
      .order("name");
    subjects = allSubjects || [];

    const { data: allTeachers } = await supabase
      .from("teachers")
      .select("*, profile:profiles(*)")
      .eq("status", "active");
    teachers = allTeachers || [];
  }

  const { data: academicYears } = await supabase
    .from("academic_years")
    .select("*")
    .order("is_current", { ascending: false });

  return (
    <TimetableDashboard
      timetables={timetables || []}
      classes={classes || []}
      subjects={subjects || []}
      teachers={teachers || []}
      academicYears={academicYears || []}
      userRole={role || "student"}
    />
  );
}

"use server";

import { createAdminClient } from "@/lib/supabase/admin";
import { revalidatePath } from "next/cache";
import { isAdmin } from "@/lib/auth-utils";

export async function provisionUser(formData: any) {
  const adminCheck = await isAdmin();
  if (!adminCheck) {
    return { success: false, message: "Unauthorized: Admin clearance required" };
  }

  try {
    const supabaseAdmin = createAdminClient();

    const { data: authData, error: authError } = await supabaseAdmin.auth.admin.createUser({
      email: formData.email,
      password: formData.password,
      email_confirm: true,
      user_metadata: {
        full_name: formData.full_name,
        role: formData.role
      }
    });

    if (authError) throw authError;
    if (!authData.user) throw new Error("Failed to create user identity");

    const userId = authData.user.id;

    const { error: profileError } = await supabaseAdmin
      .from('profiles')
      .upsert({
        id: userId,
        email: formData.email,
        full_name: formData.full_name,
        role: formData.role,
        updated_at: new Date().toISOString()
      });

    if (profileError) throw profileError;

    revalidatePath("/users");
    return { success: true, message: "Identity provisioned successfully", userId };
  } catch (error: any) {
    console.error("Error provisioning identity:", error);
    return { success: false, message: error.message || "An unexpected error occurred" };
  }
}

export async function updateIdentity(userId: string, formData: any) {
  const adminCheck = await isAdmin();
  if (!adminCheck) {
    return { success: false, message: "Unauthorized: Admin clearance required" };
  }

  try {
    const supabaseAdmin = createAdminClient();

    // 1. Update auth user (metadata and password)
    const updateData: any = {
      user_metadata: {
        full_name: formData.full_name,
        role: formData.role
      }
    };

    if (formData.password) {
      updateData.password = formData.password;
    }

    const { error: authError } = await supabaseAdmin.auth.admin.updateUserById(userId, updateData);
    if (authError) throw authError;

    // 2. Update profile
    const { error: profileError } = await supabaseAdmin
      .from('profiles')
      .update({
        full_name: formData.full_name,
        role: formData.role,
        updated_at: new Date().toISOString()
      })
      .eq('id', userId);

    if (profileError) throw profileError;

    revalidatePath("/users");
    return { success: true, message: "Identity updated successfully" };
  } catch (error: any) {
    console.error("Error updating identity:", error);
    return { success: false, message: error.message || "Failed to update identity" };
  }
}

export async function deleteIdentity(userId: string) {
  const adminCheck = await isAdmin();
  if (!adminCheck) {
    return { success: false, message: "Unauthorized: Admin clearance required" };
  }

  try {
    const supabaseAdmin = createAdminClient();

    // Cascading delete should handle profiles if configured, but we do explicit for safety
    await supabaseAdmin.from('profiles').delete().eq('id', userId);
    const { error: authError } = await supabaseAdmin.auth.admin.deleteUser(userId);
    if (authError) throw authError;

    revalidatePath("/users");
    return { success: true, message: "Identity deleted successfully" };
  } catch (error: any) {
    console.error("Error deleting identity:", error);
    return { success: false, message: error.message || "Failed to delete identity" };
  }
}

"use server";

import { createAdminClient } from "@/lib/supabase/admin";
import { revalidatePath } from "next/cache";
import { isAdminOrTeacher } from "@/lib/auth-utils";

export async function createActivity(data: {
    name: string;
    description: string;
    category: string;
    location: string;
    schedule: string;
    max_participants: number;
    teacher_in_charge?: string;
}) {
    const authorized = await isAdminOrTeacher();
    if (!authorized) return { success: false, message: "Unauthorized" };

    try {
        const supabaseAdmin = createAdminClient();
        const { error } = await supabaseAdmin
            .from("activities")
            .insert(data);

        if (error) throw error;
        revalidatePath("/activities");
        return { success: true, message: "Activity protocol initialized" };
    } catch (error: any) {
        return { success: false, message: error.message };
    }
}

export async function enrollInActivity(activityId: string, studentId: string) {
    try {
        const supabaseAdmin = createAdminClient();

        // Check capacity
        const { data: activity } = await supabaseAdmin
            .from("activities")
            .select("max_participants")
            .eq("id", activityId)
            .single();

        const { count } = await supabaseAdmin
            .from("activity_enrollments")
            .select("*", { count: 'exact', head: true })
            .eq("activity_id", activityId);

        if (activity && count !== null && count >= activity.max_participants) {
            return { success: false, message: "Activity node at maximum capacity" };
        }

        const { error } = await supabaseAdmin
            .from("activity_enrollments")
            .insert({
                activity_id: activityId,
                student_id: studentId,
                status: "enrolled"
            });

        if (error) throw error;
        revalidatePath("/activities");
        return { success: true, message: "Student successfully enrolled in activity node" };
    } catch (error: any) {
        return { success: false, message: error.message };
    }
}

