"use client";

import { useState, useRef } from "react";
import {
    Award,
    Download,
    Share2,
    Printer,
    ShieldCheck,
    GraduationCap,
    Star,
    BookOpen,
    Search,
    Plus,
    Trash2,
    Eye,
    Shield,
    Loader2
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import dynamic from 'next/dynamic';
import { CertificatePDF } from "./CertificatePDF";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { toast } from "sonner";
import { issueCertificate, revokeCertificate } from "@/app/actions/certificates";
import { Student } from "@/types/database";

const PDFDownloadLink = dynamic(
    () => import('@react-pdf/renderer').then(mod => mod.PDFDownloadLink),
    { ssr: false, loading: () => <Button variant="ghost" size="icon" disabled className="h-8 w-8 text-slate-300"><Download className="h-4 w-4" /></Button> }
);

export default function CertificatesDashboardClient({ 
    initialCertificates,
    students,
    currentUserId,
    userRole
}: { 
    initialCertificates: any[],
    students: Student[],
    currentUserId?: string,
    userRole?: string | null
}) {
    const isAdminOrTeacher = userRole === "admin" || userRole === "teacher";
    const [searchTerm, setSearchTerm] = useState("");
    const [open, setOpen] = useState(false);
    const [isIssuing, setIsIssuing] = useState(false);
    const [certificates, setCertificates] = useState(initialCertificates);

    const filteredCertificates = certificates.filter((cert) =>
        cert.reference_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        cert.certificate_type?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (cert.student?.profile?.first_name && cert.student.profile.first_name.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (cert.student?.profile?.last_name && cert.student.profile.last_name.toLowerCase().includes(searchTerm.toLowerCase()))
    );

    const handleIssue = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsIssuing(true);
        const formData = new FormData(e.currentTarget);

        try {
            const result = await issueCertificate({
                student_id: formData.get("student_id") as string,
                type: formData.get("type") as string,
                remarks: formData.get("notes") as string
            });

            if (result.success) {
                toast.success(result.message);
                setOpen(false);
                window.location.reload();
            } else {
                toast.error(result.message);
            }
        } catch (error) {
            toast.error("Failed to issue certificate");
        } finally {
            setIsIssuing(false);
        }
    };

    const handleRevoke = async (id: string) => {
        if (!confirm("Are you sure you want to revoke this certificate?")) return;

        try {
            const result = await revokeCertificate(id);
            if (result.success) {
                toast.success(result.message);
                setCertificates(prev => prev.filter(c => c.id !== id));
            } else {
                toast.error(result.message);
            }
        } catch (error) {
            toast.error("Failed to revoke certificate");
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-700 pb-12">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-4xl font-black tracking-tighter text-foreground uppercase italic underline decoration-primary/30 underline-offset-8">
                        Certificates
                    </h2>
                    <p className="text-primary font-black uppercase text-[10px] tracking-[0.3em] mt-3 bg-primary/10 w-fit px-3 py-1 rounded-sm border border-primary/20">
                        Student certificates and recognition
                    </p>
                </div>
                {isAdminOrTeacher && (
                    <div className="flex gap-x-3">
                        <Dialog open={open} onOpenChange={setOpen}>
                            <DialogTrigger asChild>
                                <Button className="rounded-sm bg-primary text-primary-foreground font-black uppercase tracking-[0.2em] text-[10px] px-8 py-6 h-auto emerald-glow shadow-2xl hover:scale-105 transition-all">
                                    {isAdminOrTeacher ? (
                                        <>
                                            <Plus className="h-4 w-4 mr-2" />
                                            Issue Certificate
                                        </>
                                    ) : (
                                        <>
                                            <Award className="h-4 w-4 mr-2" />
                                            Request Certificate
                                        </>
                                    )}
                                </Button>
                            </DialogTrigger>
                            <DialogContent className="sm:max-w-[425px] bg-card border-primary/20 rounded-sm">
                                <form onSubmit={handleIssue}>
                                    <DialogHeader>
                                        <DialogTitle className="text-xl font-black uppercase tracking-tighter italic text-primary">Issue Certificate</DialogTitle>
                                        <DialogDescription className="text-[10px] uppercase font-bold tracking-widest opacity-60">
                                            Formal recognition of academic or athletic achievement.
                                        </DialogDescription>
                                    </DialogHeader>
                                    <div className="grid gap-6 py-8">
                                        <div className="space-y-2">
                                            <p className="text-[10px] font-black uppercase tracking-widest text-foreground/60 mb-1">Select Student</p>
                                            <Select name="student_id" required>
                                                <SelectTrigger className="rounded-sm border-border bg-background h-12 text-xs font-bold uppercase tracking-tight">
                                                    <SelectValue placeholder="Search student..." />
                                                </SelectTrigger>
                                                <SelectContent className="bg-card border-border">
                                                    {students.map((s) => (
                                                        <SelectItem key={s.id} value={s.id} className="text-xs font-bold uppercase tracking-tight">
                                                            [{s.admission_number}] {s.profile?.first_name} {s.profile?.last_name}
                                                        </SelectItem>
                                                    ))}
                                                </SelectContent>
                                            </Select>
                                        </div>
                                        <div className="space-y-2">
                                            <p className="text-[10px] font-black uppercase tracking-widest text-foreground/60 mb-1">Certificate Type</p>
                                            <span className="sr-only">Credential Type</span>
                                            <Select name="type" required>
                                                <SelectTrigger className="rounded-sm border-border bg-background h-12 text-xs font-bold uppercase tracking-tight">
                                                    <SelectValue placeholder="Select type..." />
                                                </SelectTrigger>
                                                <SelectContent className="bg-card border-border">
                                                    <SelectItem value="Academic Excellence" className="text-xs font-bold uppercase tracking-tight">Academic Excellence</SelectItem>
                                                    <SelectItem value="Athletic Achievement" className="text-xs font-bold uppercase tracking-tight">Athletic Achievement</SelectItem>
                                                    <SelectItem value="Conduct & Leadership" className="text-xs font-bold uppercase tracking-tight">Conduct & Leadership</SelectItem>
                                                    <SelectItem value="Special Commendation" className="text-xs font-bold uppercase tracking-tight">Special Commendation</SelectItem>
                                                </SelectContent>
                                            </Select>
                                        </div>
                                        <div className="space-y-2">
                                            <p className="text-[10px] font-black uppercase tracking-widest text-foreground/60 mb-1">Notes</p>
                                            <Input name="notes" placeholder="Reason for issuing certificate..." className="rounded-sm border-border bg-background h-12 text-xs font-bold" />
                                        </div>
                                    </div>
                                    <DialogFooter>
                                        <Button 
                                            type="submit" 
                                            disabled={isIssuing}
                                            className="w-full bg-primary text-primary-foreground font-black uppercase tracking-[0.2em] h-14 rounded-sm emerald-glow"
                                        >
                                            {isIssuing ? "ISSUING..." : "CONFIRM ISSUANCE"}
                                        </Button>
                                    </DialogFooter>
                                </form>
                            </DialogContent>
                        </Dialog>
                    </div>
                )}
            </div>

            <div className="grid gap-8 lg:grid-cols-3">
                <div className="lg:col-span-2 space-y-6">
                    <div className="flex items-center justify-between">
                        <h3 className="text-sm font-black uppercase tracking-widest text-primary italic flex items-center gap-x-3">
                            <Shield className="h-4 w-4" />
                            Issued Certificates
                        </h3>
                        <div className="relative w-64">
                            <Search className="absolute left-3 top-2.5 h-4 w-4 text-foreground/40" />
                            <Input
                                placeholder="Search reference or name..."
                                className="pl-9 rounded-sm border-border bg-card/30 backdrop-blur-sm h-10 text-xs text-foreground placeholder:text-foreground/40"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                    </div>

                    <Card className="border-border bg-card/40 backdrop-blur-xl rounded-sm overflow-hidden shadow-2xl">
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm">
                                <thead className="bg-primary/10">
                                    <tr className="border-b border-primary/20">
                                        <th className="text-left p-6 font-black uppercase tracking-[0.2em] text-[10px] text-primary italic">Reference Number</th>
                                        <th className="text-left p-6 font-black uppercase tracking-[0.2em] text-[10px] text-primary italic">Student</th>
                                        <th className="text-left p-6 font-black uppercase tracking-[0.2em] text-[10px] text-primary italic">Status</th>
                                        <th className="text-right p-6 font-black uppercase tracking-[0.2em] text-[10px] text-primary italic">Operations</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-border">
                                    {filteredCertificates.map((cert) => (
                                        <tr key={cert.id} className="hover:bg-primary/5 border-b border-border transition-colors group">
                                            <td className="p-5">
                                                <div className="flex items-center gap-x-3">
                                                    <div className="h-12 w-12 rounded-sm bg-primary/10 flex items-center justify-center border border-primary/20 transition-all group-hover:scale-110 emerald-glow">
                                                        <Award className="h-6 w-6 text-primary" />
                                                    </div>
                                                    <div>
                                                        <p className="font-black text-foreground group-hover:text-primary transition-colors uppercase tracking-tight italic">
                                                            {cert.reference_number || "PENDING"}
                                                        </p>
                                                        <p className="text-[10px] font-black text-foreground/40 uppercase tracking-widest mt-0.5">
                                                            TYPE: {cert.certificate_type}
                                                        </p>
                                                    </div>
                                                </div>
                                            </td>
                                            <td className="p-6">
                                                <p className="font-black text-foreground uppercase tracking-tight italic text-[11px]">
                                                    {cert.student?.profile?.first_name} {cert.student?.profile?.last_name}
                                                </p>
                                                <p className="text-[10px] text-foreground/60 font-bold uppercase tracking-widest">
                                                    ID: {cert.student?.admission_number}
                                                </p>
                                            </td>
                                            <td className="p-5">
                                                <Badge className={cn(
                                                    "text-[9px] font-black px-3 py-1 rounded-sm uppercase tracking-[0.2em] shadow-lg",
                                                    cert.status === "issued" ? "bg-primary text-primary-foreground emerald-glow" : "bg-destructive text-destructive-foreground"
                                                )}>
                                                    {cert.status?.toUpperCase() || "ISSUED"}
                                                </Badge>
                                            </td>
                                            <td className="p-5 text-right">
                                                <div className="flex justify-end gap-x-2">
                                                    <PDFDownloadLink
                                                        document={<CertificatePDF certificate={cert} />}
                                                        fileName={`${cert.reference_number || 'cert'}.pdf`}
                                                    >
                                                        {({ loading }) => (
                                                            <Button
                                                                variant="ghost"
                                                                size="icon"
                                                                disabled={loading}
                                                                className="h-9 w-9 border border-border rounded-sm text-foreground/40 hover:text-primary hover:border-primary transition-all"
                                                            >
                                                                {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
                                                            </Button>
                                                        )}
                                                    </PDFDownloadLink>
                                                    {isAdminOrTeacher && (
                                                        <Button
                                                            variant="ghost"
                                                            size="icon"
                                                            onClick={() => handleRevoke(cert.id)}
                                                            className="h-9 w-9 border border-border rounded-sm text-foreground/40 hover:text-destructive hover:border-destructive transition-all"
                                                        >
                                                            <Trash2 className="h-4 w-4" />
                                                        </Button>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                    {filteredCertificates.length === 0 && (
                                        <tr>
                                            <td colSpan={4} className="text-center p-12 text-foreground/30 text-[10px] font-black uppercase tracking-widest">
                                                No institutional records detected.
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </Card>
                </div>

                <div className="space-y-6">
                    <Card className="border-border bg-card/40 backdrop-blur-xl rounded-sm overflow-hidden shadow-2xl">
                        <CardHeader className="bg-primary/10 border-b border-primary/20 p-6">
                            <CardTitle className="text-[11px] font-black uppercase tracking-[0.2em] text-primary flex items-center gap-x-3 italic">
                                <Star className="h-4 w-4" />
                                Certificate Preview
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="p-8 bg-background/50">
                            <div className="aspect-[1.414/1] w-full bg-slate-50 shadow-2xl border-[12px] border-primary/10 relative overflow-hidden flex flex-col items-center justify-center p-6 text-center group transition-all hover:border-primary/20">
                                <div className="absolute inset-0 opacity-5 pointer-events-none flex items-center justify-center">
                                    <GraduationCap className="h-32 w-32" />
                                </div>
                                <Award className="h-8 w-8 text-slate-800 mb-2" />
                                <h2 className="text-lg font-serif italic text-slate-900 leading-tight">Certificate of Achievement</h2>
                                <p className="text-[6px] tracking-widest text-slate-500 uppercase mt-2 mb-4">Awarded To</p>
                                <h3 className="text-xl font-black text-slate-900 mb-4 uppercase italic">STUDENT NAME</h3>
                                <div className="absolute bottom-4 left-4 right-4 flex justify-between border-t border-slate-200 pt-2">
                                    <div className="text-left w-1/3">
                                        <p className="text-[4px] font-black uppercase text-slate-400">Date Issued</p>
                                        <div className="h-px bg-slate-200 w-full mt-1"></div>
                                    </div>
                                    <div className="h-6 w-6 rounded-sm border border-slate-900 flex items-center justify-center -mt-2 bg-white relative z-10 shadow-lg">
                                        <ShieldCheck className="h-3 w-3 text-slate-900" />
                                    </div>
                                    <div className="text-right w-1/3">
                                        <p className="text-[4px] font-black uppercase text-slate-400">Registrar</p>
                                        <div className="h-px bg-slate-200 w-full mt-1"></div>
                                    </div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    <Card className="border-border bg-primary/10 text-foreground p-8 relative overflow-hidden group shadow-2xl rounded-sm">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
                            <BookOpen className="h-16 w-16 text-primary" />
                        </div>
                        <h4 className="text-lg font-black tracking-tight mb-2 uppercase text-primary italic">
                            Secure Records
                        </h4>
                        <p className="text-xs text-foreground/70 font-bold leading-relaxed uppercase tracking-tighter">
                            All certificates are securely stored and verified in our database.
                        </p>
                        <Button className="mt-8 w-full bg-primary text-primary-foreground font-black rounded-sm h-12 hover:scale-[1.02] transition-all emerald-glow uppercase tracking-[0.2em] text-[9px]">
                            VIEW SECURITY LOGS
                        </Button>
                    </Card>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Class } from "@/types/database";
import { toast } from "sonner";
import { createClass, updateClass } from "@/app/actions/classes";
import { useRouter } from "next/navigation";

const classSchema = z.object({
  name: z.string().min(2, "Class name is too short"),
  capacity: z
    .string()
    .refine((val) => !isNaN(Number(val)), "Capacity must be a number")
    .transform(Number),
  room_number: z.string().min(1, "Room number is required"),
});

type ClassFormValues = z.infer<typeof classSchema>;

interface ClassFormProps {
  initialData?: Class | null;
  onSuccess: () => void;
}

export function ClassForm({ initialData, onSuccess }: ClassFormProps) {
  const router = useRouter();

  type RawFormValues = {
    name: string;
    capacity: string;
    room_number: string;
  };

  const form = useForm<RawFormValues>({
    resolver: zodResolver(classSchema) as any,
    defaultValues: {
      name: initialData?.name || "",
      capacity: initialData?.capacity?.toString() || "",
      room_number: initialData?.room_number || "",
    },
  });

  async function onSubmit(data: RawFormValues) {
    try {
      const payload = {
        name: data.name,
        capacity: Number(data.capacity),
        room_number: data.room_number,
      };

      let result;
      if (initialData) {
        result = await updateClass(initialData.id, payload);
      } else {
        result = await createClass(payload);
      }

      if (result.success) {
        toast.success(initialData ? "Class updated successfully" : "Class created successfully");
        router.refresh();
        onSuccess();
      } else {
        toast.error(result.error || "Failed to save class");
      }
    } catch (error) {
      toast.error("An unexpected error occurred");
    }
  }

    return (
        <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-8 p-8 reveal-2">
                <FormField
                    control={form.control}
                    name="name"
                    render={({ field }) => (
                        <FormItem className="space-y-3">
                            <FormLabel className="text-[10px] font-bold uppercase tracking-widest text-primary/60 italic">Class Name</FormLabel>
                            <FormControl>
                                <Input 
                                    placeholder="e.g. Grade 10-Alpha" 
                                    className="h-12 bg-card border-border rounded-lg font-bold text-[11px] uppercase tracking-widest placeholder:text-muted-foreground/30 focus-visible:ring-primary/50 transition-all"
                                    {...field} 
                                />
                            </FormControl>
                            <FormMessage className="text-[9px] font-bold uppercase tracking-widest text-destructive italic" />
                        </FormItem>
                    )}
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <FormField
                        control={form.control}
                        name="capacity"
                        render={({ field }) => (
                            <FormItem className="space-y-3">
                                <FormLabel className="text-[10px] font-bold uppercase tracking-widest text-primary/60 italic">Capacity</FormLabel>
                                <FormControl>
                                    <Input 
                                        type="number" 
                                        placeholder="e.g. 30" 
                                        className="h-12 bg-card border-border rounded-lg font-bold text-[11px] uppercase tracking-widest placeholder:text-muted-foreground/30 focus-visible:ring-primary/50 transition-all"
                                        {...field} 
                                    />
                                </FormControl>
                                <FormMessage className="text-[9px] font-bold uppercase tracking-widest text-destructive italic" />
                            </FormItem>
                        )}
                    />
                    <FormField
                        control={form.control}
                        name="room_number"
                        render={({ field }) => (
                            <FormItem className="space-y-3">
                                <FormLabel className="text-[10px] font-bold uppercase tracking-widest text-primary/60 italic">Room Number</FormLabel>
                                <FormControl>
                                    <Input 
                                        placeholder="e.g. B-201" 
                                        className="h-12 bg-card border-border rounded-lg font-bold text-[11px] uppercase tracking-widest placeholder:text-muted-foreground/30 focus-visible:ring-primary/50 transition-all"
                                        {...field} 
                                    />
                                </FormControl>
                                <FormMessage className="text-[9px] font-bold uppercase tracking-widest text-destructive italic" />
                            </FormItem>
                        )}
                    />
                </div>

                <div className="flex items-center justify-end gap-x-4 pt-8 border-t border-border">
                    <button 
                        type="button" 
                        onClick={() => onSuccess()}
                        className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground hover:text-foreground transition-colors italic"
                    >
                        Cancel
                    </button>
                    <Button 
                        type="submit"
                        className="h-12 px-8 bg-primary text-primary-foreground font-bold rounded-lg shadow-sm uppercase tracking-widest text-[9px] transition-all hover:scale-105"
                    >
                        {initialData ? "Update Class" : "Create Class"}
                    </Button>
                </div>
            </form>
        </Form>
    );
}

"use client";

import { useState } from "react";
import {
    MoreHorizontal,
    Pencil,
    Trash2,
    Plus,
    Users,
    School,
    DoorOpen,
    Hash,
    Search,
    Building2
} from "lucide-react";
import { cn } from "@/lib/utils";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Class } from "@/types/database";
import { toast } from "sonner";
import { ClassForm } from "./ClassForm";
import { deleteClass } from "@/app/actions/classes";
import { useRouter } from "next/navigation";

interface ClassListProps {
    initialData: Class[];
    userRole?: string | null;
}

export function ClassList({ initialData, userRole }: ClassListProps) {
    const isAdminOrTeacher = userRole === "admin" || userRole === "teacher";
    const router = useRouter();
    const [data, setData] = useState<Class[]>(initialData);
    const [searchTerm, setSearchTerm] = useState("");
    const [isOpen, setIsOpen] = useState(false);
    const [editingClass, setEditingClass] = useState<Class | null>(null);

    const filteredData = data.filter((cls) =>
        cls.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (cls.room_number && cls.room_number.toLowerCase().includes(searchTerm.toLowerCase()))
    );

    const onAdd = () => {
        setEditingClass(null);
        setIsOpen(true);
    };

    const onEdit = (cls: Class) => {
        setEditingClass(cls);
        setIsOpen(true);
    };

    const onDelete = async (id: string) => {
        if (!confirm("Are you sure you want to delete this class?")) return;
        const res = await deleteClass(id);
        if (res.success) {
            toast.success("Class deleted successfully");
            router.refresh();
            setData(data.filter(c => c.id !== id));
        } else {
            toast.error(res.error || "Failed to delete class");
        }
    };

    const totalCapacity = data.reduce((acc, curr) => acc + (curr.capacity || 0), 0);
    const uniqueRooms = new Set(data.map(c => c.room_number).filter(Boolean)).size;

    return (
        <div className="space-y-12 reveal-1">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 border-b border-white/5 pb-10">
                <div className="relative w-full max-w-md">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-primary" />
                    <Input
                        placeholder="Search classes..."
                        className="pl-12 bg-card border-border h-12 font-bold text-[10px] uppercase tracking-widest placeholder:text-muted-foreground/50 focus-visible:ring-primary/50 rounded-lg"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>

                {isAdminOrTeacher && (
                    <Button
                        onClick={onAdd}
                        className="h-12 px-8 bg-primary text-primary-foreground font-bold rounded-lg shadow-sm uppercase tracking-widest text-[9px] transition-all hover:scale-105"
                    >
                        <Plus className="h-4 w-4 mr-2" /> Add New Class
                    </Button>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
                <Card className="bg-card border-border p-6 relative overflow-hidden group hover:border-primary/50 transition-all rounded-xl shadow-sm">
                    <School className="absolute right-[-10px] bottom-[-10px] h-16 w-16 text-primary opacity-5 group-hover:scale-110 transition-transform" />
                    <p className="text-[10px] font-bold uppercase tracking-widest text-primary/60 mb-2 italic">Total Classes</p>
                    <h3 className="text-4xl font-bold tracking-tight text-foreground transition-colors">{data.length}</h3>
                    <div className="h-1 w-full bg-muted mt-6 rounded-full overflow-hidden">
                        <div className="h-full bg-primary w-[65%]" />
                    </div>
                </Card>
                <Card className="bg-card border-border p-6 relative overflow-hidden group hover:border-primary/50 transition-all rounded-xl shadow-sm">
                    <Users className="absolute right-[-10px] bottom-[-10px] h-16 w-16 text-primary opacity-5 group-hover:scale-110 transition-transform" />
                    <p className="text-[10px] font-bold uppercase tracking-widest text-primary/60 mb-2 italic">Total Capacity</p>
                    <h3 className="text-4xl font-bold tracking-tight text-foreground transition-colors">{totalCapacity}</h3>
                    <div className="h-1 w-full bg-muted mt-6 rounded-full overflow-hidden">
                        <div className="h-full bg-primary w-[45%]" />
                    </div>
                </Card>
                <Card className="bg-card border-border p-6 relative overflow-hidden group hover:border-primary/50 transition-all rounded-xl shadow-sm">
                    <DoorOpen className="absolute right-[-10px] bottom-[-10px] h-16 w-16 text-primary opacity-5 group-hover:scale-110 transition-transform" />
                    <p className="text-[10px] font-bold uppercase tracking-widest text-primary/60 mb-2 italic">Allocated Rooms</p>
                    <h3 className="text-4xl font-bold tracking-tight text-foreground transition-colors">{uniqueRooms}</h3>
                    <div className="h-1 w-full bg-muted mt-6 rounded-full overflow-hidden">
                        <div className="h-full bg-primary w-[82%]" />
                    </div>
                </Card>
                <Card className="bg-card border-border p-6 relative overflow-hidden group hover:border-primary/50 transition-all rounded-xl shadow-sm">
                    <Building2 className="absolute right-[-10px] bottom-[-10px] h-16 w-16 text-primary opacity-5 group-hover:scale-110 transition-transform" />
                    <p className="text-[10px] font-bold uppercase tracking-widest text-primary/60 mb-2 italic">System Status</p>
                    <h3 className="text-2xl font-bold tracking-tight text-foreground uppercase mt-1 leading-none">Verified</h3>
                    <div className="h-1 w-full bg-muted mt-6 rounded-full overflow-hidden">
                        <div className="h-full bg-primary w-full" />
                    </div>
                </Card>
            </div>

            <div className="bg-card rounded-xl border border-border overflow-hidden shadow-sm">
                <table className="w-full text-left">
                    <thead className="bg-muted/50">
                        <tr className="border-b border-border">
                            <th className="px-6 py-4 text-[10px] font-bold uppercase tracking-widest text-primary/60 italic">Class Name</th>
                            <th className="px-6 py-4 text-[10px] font-bold uppercase tracking-widest text-primary/60 italic">Capacity</th>
                            <th className="px-6 py-4 text-[10px] font-bold uppercase tracking-widest text-primary/60 italic">Room No.</th>
                            {isAdminOrTeacher && <th className="px-6 py-4 text-right text-[10px] font-bold uppercase tracking-widest text-primary/60 italic">Actions</th>}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {filteredData.length === 0 ? (
                            <tr>
                                <td colSpan={isAdminOrTeacher ? 4 : 3} className="h-64 text-center">
                                    <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground/40 italic">No classes matched the search criteria.</p>
                                </td>
                            </tr>
                        ) : (
                            filteredData.map((cls) => (
                                <tr key={cls.id} className="group hover:bg-muted/30 transition-all duration-300">
                                    <td className="px-6 py-5 font-bold text-foreground uppercase tracking-tight text-sm group-hover:text-primary transition-colors italic">
                                        {cls.name}
                                    </td>
                                    <td className="px-6 py-5 text-sm font-bold text-foreground/80">
                                        <div className="flex items-center gap-x-3 italic">
                                            <Users className="h-4 w-4 text-primary" />
                                            {cls.capacity || "N/A"}
                                        </div>
                                    </td>
                                    <td className="px-6 py-5 text-[11px] font-bold uppercase tracking-widest text-muted-foreground/60 italic">
                                        {cls.room_number || "UNALLOCATED"}
                                    </td>
                                    {isAdminOrTeacher && (
                                        <td className="px-6 py-5 text-right">
                                            <DropdownMenu>
                                                <DropdownMenuTrigger asChild>
                                                    <Button variant="ghost" className="h-9 w-9 p-0 text-muted-foreground hover:text-primary hover:bg-primary/10 rounded-lg">
                                                        <MoreHorizontal className="h-4 w-4" />
                                                    </Button>
                                                </DropdownMenuTrigger>
                                                <DropdownMenuContent align="end" className="bg-card border-border shadow-lg p-2 min-w-[200px] rounded-xl">
                                                    <DropdownMenuLabel className="text-[9px] font-bold uppercase tracking-widest opacity-40 px-3 py-2">Actions</DropdownMenuLabel>
                                                    <DropdownMenuItem
                                                        onClick={() => onEdit(cls)}
                                                        className="gap-x-3 cursor-pointer font-bold uppercase text-[10px] tracking-widest focus:bg-primary focus:text-white p-3 rounded-lg italic transition-all"
                                                    >
                                                        <Pencil className="h-3.5 w-3.5" /> Edit Class
                                                    </DropdownMenuItem>
                                                    <DropdownMenuSeparator className="bg-border my-1" />
                                                    <DropdownMenuItem
                                                        onClick={() => onDelete(cls.id)}
                                                        className="gap-x-3 text-destructive focus:text-white focus:bg-destructive cursor-pointer font-bold uppercase text-[10px] tracking-widest p-3 rounded-lg italic transition-all"
                                                    >
                                                        <Trash2 className="h-3.5 w-3.5" /> Delete Class
                                                    </DropdownMenuItem>
                                                </DropdownMenuContent>
                                            </DropdownMenu>
                                        </td>
                                    )}
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            <Dialog open={isOpen} onOpenChange={setIsOpen}>
                <DialogContent className="bg-card border-border p-0 overflow-hidden max-w-xl rounded-2xl shadow-2xl">
                    <div className="p-8 bg-muted/30 border-b border-border relative overflow-hidden">
                        <School className="absolute right-[-20px] top-[-20px] h-32 w-32 text-primary opacity-5 rotate-12" />
                        <h3 className="text-2xl font-bold uppercase tracking-tight text-foreground relative z-10">
                            {editingClass ? "Edit Class" : "Add New Class"}
                        </h3>
                        <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground/60 mt-2 relative z-10 italic">Configure class details and capacity</p>
                    </div>
                    <div className="p-6">
                        <ClassForm
                            initialData={editingClass}
                            onSuccess={() => setIsOpen(false)}
                        />
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

