              {editingExam ? "Edit Exam Schedule" : "Schedule New Exam"}
            </DialogTitle>
            <DialogDescription>
              Manage examination schedules and academic years.
            </DialogDescription>
          </DialogHeader>
          <ExamForm
            initialData={editingExam}
            academicYears={academicYears}
            onSuccess={() => setIsOpen(false)}
          />
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
    FileText, Plus, ClipboardCheck, Calendar, Award, BookOpen, Users, BarChart3, Pencil, Trash2,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Calendar as BigCalendar, dateFnsLocalizer, View } from "react-big-calendar";
import { format, parse, startOfWeek, getDay } from "date-fns";
import { enUS } from "date-fns/locale/en-US";
import "react-big-calendar/lib/css/react-big-calendar.css";
import "@/styles/calendar-overrides.css"; // We will create this for glassmorphism
import { createExam, deleteExam, saveMarks, getMarksByExam } from "@/app/actions/exams";
import { useRouter } from "next/navigation";
import { cn } from "@/lib/utils";

interface ExamsDashboardProps {
    exams: any[];
    classes: any[];
    subjects: any[];
    academicYears: any[];
    students: any[];
    userRole: string;
}

const locales = {
    "en-US": enUS,
};

const localizer = dateFnsLocalizer({
    format,
    parse,
    startOfWeek,
    getDay,
    locales,
});

export function ExamsDashboard({ exams, classes, subjects, academicYears, students, userRole }: ExamsDashboardProps) {
    const router = useRouter();
    const [isCreateOpen, setIsCreateOpen] = useState(false);
    const [isMarksOpen, setIsMarksOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [selectedExam, setSelectedExam] = useState<any>(null);
    const [marks, setMarks] = useState<Record<string, string>>({});
    const [existingMarks, setExistingMarks] = useState<any[]>([]);
    const [calendarView, setCalendarView] = useState<View>("month");

    const currentAY = academicYears.find((ay: any) => ay.is_current) || academicYears[0];

    const [examForm, setExamForm] = useState({
        name: "", subject_id: "", class_id: "", date: "", max_marks: "100", passing_marks: "35",
        academic_year_id: currentAY?.id || "",
    });

    const handleCreateExam = async () => {
        setLoading(true);
        const result = await createExam({
            ...examForm,
            max_marks: parseInt(examForm.max_marks) || 100,
            passing_marks: parseInt(examForm.passing_marks) || 35,
        });
        setLoading(false);
        if (result.success) {
            setIsCreateOpen(false);
            setExamForm({ name: "", subject_id: "", class_id: "", date: "", max_marks: "100", passing_marks: "35", academic_year_id: currentAY?.id || "" });
            router.refresh();
        }
    };

    const handleDeleteExam = async (id: string) => {
        setLoading(true);
        await deleteExam(id);
        setLoading(false);
        router.refresh();
    };

    const handleOpenMarks = async (exam: any) => {
        setSelectedExam(exam);
        setLoading(true);
        const result = await getMarksByExam(exam.id);
        if (result.success && result.data) {
            setExistingMarks(result.data);
            const marksObj: Record<string, string> = {};
            result.data.forEach((m: any) => { marksObj[m.student_id] = String(m.marks_obtained); });
            setMarks(marksObj);
        }
        setLoading(false);
        setIsMarksOpen(true);
    };

    const handleSaveMarks = async () => {
        if (!selectedExam) return;
        setLoading(true);
        const marksArr = Object.entries(marks)
            .filter(([_, v]) => v !== "")
            .map(([studentId, obtained]) => ({
                exam_id: selectedExam.id,
                student_id: studentId,
                subject_id: selectedExam.subject_id,
                marks_obtained: parseInt(obtained) || 0,
            }));
        await saveMarks(marksArr);
        setLoading(false);
        setIsMarksOpen(false);
        router.refresh();
    };

    const examStudents = selectedExam
        ? students.filter((s: any) => s.class_id === selectedExam.class_id)
        : [];

    const upcoming = exams.filter(e => new Date(e.date) >= new Date());
    const completed = exams.filter(e => new Date(e.date) < new Date());

    const calendarEvents = exams.map(e => {
        // Assume exams default to a standard time if we only have dates
        const dateStr = e.date;
        const start = new Date(dateStr);
        start.setHours(9, 0, 0); // Default to 9 AM
        const end = new Date(dateStr);
        end.setHours(12, 0, 0); // Default 3 hours

        return {
            id: e.id,
            title: `${e.name} (${e.class?.name || "N/A"})`,
            start,
            end,
            resource: e,
        };
    });

    return (
        <div className="space-y-12 reveal-1">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 border-b border-primary/10 pb-10">
                <div className="flex items-center gap-x-8">
                    <div className="h-16 w-16 bg-primary/10 border border-primary/20 flex items-center justify-center text-primary rounded-lg group hover:bg-primary hover:text-primary-foreground transition-all duration-300">
                        <Award className="h-8 w-8 transition-all duration-300" />
                    </div>
                    <div>
                        <div className="relative">
                            <h1 className="text-4xl font-bold uppercase tracking-tight text-foreground leading-none">Exam <span className="text-primary italic">Management</span></h1>
                        </div>
                        <p className="text-[10px] font-mono font-medium uppercase tracking-widest text-foreground/40 mt-3 flex items-center gap-2">
                            <span className="h-1 w-1 rounded-full bg-primary" /> Manage School Examinations
                        </p>
                    </div>
                </div>

                {(userRole === "admin" || userRole === "teacher") && (
                    <Button
                        onClick={() => setIsCreateOpen(true)}
                        className="h-12 px-8 bg-primary text-primary-foreground font-bold rounded-lg shadow-sm hover:scale-105 transition-all"
                    >
                        <span className="flex items-center gap-x-2 uppercase tracking-wider text-[10px]">
                            Create Exam
                            <Plus className="h-4 w-4" />
                        </span>
                    </Button>
                )}
            </div>

            <Tabs defaultValue="list" className="w-full">
                <TabsList className="bg-muted/50 border border-border p-1 rounded-lg h-auto mb-8 flex items-center gap-2">
                    <TabsTrigger value="list" className="rounded-md px-8 py-3 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground font-bold text-[11px] uppercase tracking-wide transition-all italic">
                        <span className="flex items-center gap-x-2">
                            <ClipboardCheck className="h-4 w-4" /> Exam List
                        </span>
                    </TabsTrigger>
                    <TabsTrigger value="calendar" className="rounded-md px-8 py-3 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground font-bold text-[11px] uppercase tracking-wide transition-all italic text-foreground/40">
                        <span className="flex items-center gap-x-2">
                            <Calendar className="h-4 w-4" /> Exam Calendar
                        </span>
                    </TabsTrigger>
                </TabsList>

                <TabsContent value="list" className="mt-0 space-y-12">
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                        {[
                            { label: "Total Exams", value: exams.length, icon: FileText, width: "78%" },
                            { label: "Active Participants", value: students.length, icon: Users, width: "92%" },
                            { label: "Subject Coverage", value: new Set(exams.map(e => e.subject_id)).size, icon: BookOpen, width: "64%" },
                            { label: "Current Cycle", value: "Verified", icon: Calendar, width: "100%" },
                        ].map((stat, i) => (
                            <div key={i} className="bg-card p-6 border border-border rounded-xl shadow-sm hover:border-primary/50 transition-all group">
                                <div className="relative z-10">
                                    <stat.icon className="absolute right-[-10px] bottom-[-10px] h-16 w-16 text-primary opacity-5 group-hover:scale-110 group-hover:opacity-10 transition-all" />
                                    <p className="text-[9px] font-mono font-bold uppercase tracking-widest text-primary/60 mb-4 italic">{stat.label}</p>
                                    <h3 className="text-4xl font-bold italic tracking-tight text-foreground group-hover:text-primary transition-all leading-none">
                                        {stat.value}
                                    </h3>
                                    <div className="h-1 w-full bg-muted mt-6 rounded-full overflow-hidden">
                                        <div 
                                            className="h-full bg-primary transition-all duration-1000 ease-out" 
                                            style={{ width: stat.width }} 
                                        />
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                        <table className="w-full text-left border-collapse">
                            <thead className="bg-muted/50">
                                <tr>
                                    <th className="px-6 py-4 text-[10px] font-bold uppercase tracking-widest text-muted-foreground border-b border-border">Exam Name</th>
                                    <th className="px-6 py-4 text-[10px] font-bold uppercase tracking-widest text-muted-foreground border-b border-border">Class</th>
                                    <th className="px-6 py-4 text-[10px] font-bold uppercase tracking-widest text-muted-foreground border-b border-border">Date</th>
                                    <th className="px-6 py-4 text-[10px] font-bold uppercase tracking-widest text-muted-foreground border-b border-border">Total Marks</th>
                                    <th className="px-6 py-4 text-right text-[10px] font-bold uppercase tracking-widest text-muted-foreground border-b border-border">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-primary/5 font-medium tracking-tight">
                                {exams.map((exam) => (
                                    <tr key={exam.id} className="group hover:bg-primary/[0.02] transition-all duration-500">
                                        <td className="px-6 py-6">
                                            <div>
                                                <p className="font-bold text-foreground uppercase tracking-tight text-lg group-hover:text-primary transition-colors leading-none mb-2">
                                                    {exam.name}
                                                </p>
                                                <div className="flex items-center gap-2 text-muted-foreground">
                                                    <BookOpen className="h-3 w-3" />
                                                    <p className="text-[10px] font-mono font-bold uppercase tracking-widest">{exam.subject?.name}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-6 font-mono font-bold text-xs uppercase tracking-wider text-muted-foreground">
                                             {exam.class?.name}
                                        </td>
                                        <td className="px-6 py-6">
                                            <div className="flex flex-col gap-1">
                                                <p className="font-mono font-bold text-[12px] uppercase tracking-wider text-foreground">
                                                    {format(new Date(exam.date), "dd-MM-yyyy")}
                                                </p>
                                            </div>
                                        </td>
                                        <td className="px-12 py-10">
                                            <div className="flex items-center gap-x-4">
                                                <div className="flex flex-col items-end">
                                                    <span className="text-2xl font-black italic text-foreground tracking-tighter leading-none">{exam.max_marks}</span>
                                                    <span className="text-[9px] font-mono font-black uppercase tracking-widest text-foreground/20">MAX</span>
                                                </div>
                                                <div className="h-8 w-px bg-primary/20" />
                                                <div className="flex flex-col">
                                                    <span className="text-[11px] font-mono font-black uppercase tracking-widest text-primary italic leading-none">{exam.passing_marks}</span>
                                                    <span className="text-[9px] font-mono font-black uppercase tracking-widest text-primary/30">PASSING</span>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-12 py-10 text-right">
                                            <div className="flex items-center justify-end gap-x-4">
                                                {(userRole === "admin" || userRole === "teacher") && (
                                                    <Button 
                                                        onClick={() => handleOpenMarks(exam)}
                                                        size="sm"
                                                        className="bg-primary hover:bg-primary/90 text-primary-foreground font-bold uppercase tracking-wider text-[10px]"
                                                    >
                                                        <span className="flex items-center gap-x-2">
                                                            <Plus className="h-3 w-3" /> Enter Results
                                                        </span>
                                                    </Button>
                                                )}
                                                <Button 
                                                    variant="ghost" 
                                                    size="icon"
                                                    className="text-muted-foreground hover:text-primary hover:bg-primary/10 rounded-lg border border-transparent hover:border-primary/20"
                                                >
                                                    <Pencil className="h-4 w-4" />
                                                </Button>
                                                {(userRole === "admin" || userRole === "teacher") && (
                                                    <Button 
                                                        onClick={() => handleDeleteExam(exam.id)}
                                                        variant="ghost" 
                                                        size="icon"
                                                        className="text-muted-foreground hover:text-red-500 hover:bg-red-500/10 rounded-lg border border-transparent hover:border-red-500/20"
                                                    >
                                                        <Trash2 className="h-4 w-4" />
                                                    </Button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </TabsContent>

                <TabsContent value="calendar">
                    <div className="glass-panel p-8 rounded-sm border border-white/10 overflow-hidden shadow-2xl">
                        <div className="h-[700px] font-black uppercase tracking-widest italic text-[10px]">
                            <BigCalendar
                                localizer={localizer}
                                events={calendarEvents}
                                startAccessor="start"
                                endAccessor="end"
                                className="premium-calendar"
                                views={["month", "week", "agenda"]}
                                view={calendarView}
                                onView={(v) => setCalendarView(v)}
                            />
                        </div>
                    </div>
                </TabsContent>
            </Tabs>

            {/* Create Exam Dialog */}
            <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
                <DialogContent className="bg-card border border-border p-0 overflow-hidden max-w-2xl rounded-xl shadow-2xl">
                    <div className="p-8 bg-muted/50 border-b border-border relative overflow-hidden">
                        <div className="relative z-10">
                            <h3 className="text-3xl font-bold uppercase tracking-tight text-foreground leading-none">
                                Exam <span className="text-primary italic">Details</span>
                            </h3>
                            <p className="text-[10px] font-mono font-medium uppercase tracking-widest text-foreground/40 mt-3 flex items-center gap-2">
                                <span className="h-1 w-1 rounded-full bg-primary" /> Create a new exam
                            </p>
                        </div>
                    </div>
                    
                    <div className="p-8 space-y-8">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                            <div className="space-y-4">
                                <Label className="text-[11px] font-mono font-black uppercase tracking-[0.4em] text-primary italic">Exam Name</Label>
                                <Input 
                                    placeholder="E.G. FIRST TERM FINALS" 
                                    className="h-16 bg-white/[0.03] border-primary/10 rounded-none font-black text-[12px] uppercase tracking-[0.2em] italic placeholder:text-foreground/10 focus-visible:ring-primary/50 focus-visible:bg-primary/5 skew-x-[-8deg] transition-all"
                                    value={examForm.name} 
                                    onChange={(e) => setExamForm({ ...examForm, name: e.target.value })} 
                                />
                            </div>
                            <div className="space-y-4">
                                <Label className="text-[11px] font-mono font-black uppercase tracking-[0.4em] text-primary italic">Exam Date</Label>
                                <Input 
                                    type="date" 
                                    className="h-16 bg-white/[0.03] border-primary/10 rounded-none font-black text-[12px] uppercase tracking-[0.2em] focus-visible:ring-primary/50 focus-visible:bg-primary/5 skew-x-[-8deg] transition-all [&::-webkit-calendar-picker-indicator]:invert"
                                    value={examForm.date} 
                                    onChange={(e) => setExamForm({ ...examForm, date: e.target.value })} 
                                />
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                            <div className="space-y-4">
                                <Label className="text-[11px] font-mono font-black uppercase tracking-[0.4em] text-primary italic">Class</Label>
                                <Select onValueChange={(v) => setExamForm({ ...examForm, class_id: v })}>
                                    <SelectTrigger className="h-16 bg-white/[0.03] border-primary/10 rounded-none font-black text-[12px] uppercase tracking-[0.2em] italic focus:ring-primary/50 skew-x-[-8deg] transition-all">
                                        <SelectValue placeholder="Select Class" />
                                    </SelectTrigger>
                                    <SelectContent className="glass-panel border-primary/10 rounded-none">
                                        {classes.map(c => <SelectItem key={c.id} value={c.id} className="font-black uppercase text-[10px] tracking-widest">{c.name}</SelectItem>)}
                                    </SelectContent>
                                </Select>
                            </div>
                            <div className="space-y-4">
                                <Label className="text-[11px] font-mono font-black uppercase tracking-[0.4em] text-primary italic">Subject</Label>
                                <Select onValueChange={(v) => setExamForm({ ...examForm, subject_id: v })}>
                                    <SelectTrigger className="h-16 bg-white/[0.03] border-primary/10 rounded-none font-black text-[12px] uppercase tracking-[0.2em] italic focus:ring-primary/50 skew-x-[-8deg] transition-all">
                                        <SelectValue placeholder="Select Subject" />
                                    </SelectTrigger>
                                    <SelectContent className="glass-panel border-primary/10 rounded-none">
                                        {subjects.map(s => <SelectItem key={s.id} value={s.id} className="font-black uppercase text-[10px] tracking-widest">{s.name}</SelectItem>)}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 border-t border-border pt-8">
                            <div className="space-y-3">
                                <Label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Maximum Marks</Label>
                                <Input 
                                    type="number" 
                                    className="h-12 bg-background border-border rounded-lg font-bold text-lg"
                                    value={examForm.max_marks} 
                                    onChange={(e) => setExamForm({ ...examForm, max_marks: e.target.value })} 
                                />
                            </div>
                            <div className="space-y-3">
                                <Label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Passing Marks</Label>
                                <Input 
                                    type="number" 
                                    className="h-12 bg-background border-border rounded-lg font-bold text-lg text-primary"
                                    value={examForm.passing_marks} 
                                    onChange={(e) => setExamForm({ ...examForm, passing_marks: e.target.value })} 
                                />
                            </div>
                        </div>

                        <div className="flex items-center justify-end gap-x-6 pt-8 border-t border-border">
                            <Button 
                                variant="ghost"
                                onClick={() => setIsCreateOpen(false)}
                                className="text-[11px] font-bold uppercase tracking-widest text-muted-foreground"
                            >
                                Cancel
                            </Button>
                            <Button 
                                onClick={handleCreateExam}
                                disabled={loading}
                                className="h-12 px-10 bg-primary text-primary-foreground font-bold rounded-lg shadow-md uppercase tracking-wider text-[11px] hover:scale-105 transition-all"
                            >
                                {loading ? "Saving..." : "Save Exam"}
                            </Button>
                        </div>
                    </div>
                </DialogContent>
            </Dialog>

            {/* Marks Assessment Dialog */}
            <Dialog open={isMarksOpen} onOpenChange={setIsMarksOpen}>
                <DialogContent className="bg-card border border-border p-0 overflow-hidden max-w-5xl max-h-[90vh] flex flex-col rounded-xl shadow-2xl">
                    <div className="p-8 bg-muted/50 border-b border-border relative overflow-hidden flex-shrink-0">
                        <div className="relative z-10">
                            <h3 className="text-3xl font-bold uppercase tracking-tight text-foreground leading-none">
                                Exam <span className="text-primary italic">Results</span>
                            </h3>
                            <div className="flex flex-wrap items-center gap-6 mt-4">
                                <p className="text-[10px] font-mono font-medium uppercase tracking-widest text-foreground/40 italic flex items-center gap-2">
                                    <span className="h-1 w-1 rounded-full bg-primary" /> Exam: {selectedExam?.name}
                                </p>
                                <p className="text-[10px] font-mono font-medium uppercase tracking-widest text-foreground/40 italic flex items-center gap-2 border-l border-border pl-6">
                                    <span className="h-1 w-1 rounded-full bg-primary/50" /> Max Marks: {selectedExam?.max_marks} Points
                                </p>
                            </div>
                        </div>
                    </div>
                    
                    <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                        <div className="glass-panel p-2 rounded-none border border-primary/10 mb-10 overflow-hidden">
                            <table className="w-full text-left border-collapse">
                                <thead className="bg-primary/10">
                                    <tr>
                                        <th className="px-10 py-8 text-[11px] font-mono font-black uppercase tracking-[0.5em] text-primary italic border-b border-primary/10">Student Name</th>
                                        <th className="px-10 py-8 text-right text-[11px] font-mono font-black uppercase tracking-[0.5em] text-primary italic border-b border-primary/10">Marks Obtained</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-primary/5">
                                    {examStudents.length === 0 ? (
                                        <tr><td colSpan={2} className="py-16 text-center text-muted-foreground/30 font-bold uppercase tracking-widest text-xs italic">No student records found</td></tr>
                                    ) : (
                                        examStudents.map((student: any) => (
                                            <tr key={student.id} className="group hover:bg-muted/30 transition-all">
                                                <td className="px-8 py-6">
                                                    <div className="flex items-center gap-x-6">
                                                        <div className="h-10 w-10 flex items-center justify-center bg-muted font-mono font-bold text-[10px] text-muted-foreground border border-border rounded-lg group-hover:bg-primary group-hover:text-primary-foreground transition-all">
                                                            {student.id.slice(0, 3)}
                                                        </div>
                                                        <div>
                                                            <p className="font-bold text-foreground uppercase tracking-tight text-md group-hover:text-primary transition-colors leading-none mb-1">
                                                                {student.profile?.first_name} {student.profile?.last_name}
                                                            </p>
                                                            <p className="text-[9px] font-mono font-medium uppercase tracking-wider text-muted-foreground/60">Roll No: {student.admission_number || student.id.slice(0, 12)}</p>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="px-8 py-6 text-right">
                                                    <div className="relative inline-block">
                                                        <Input
                                                            type="number"
                                                            placeholder="0"
                                                            className="w-32 h-12 bg-muted/50 border-border rounded-lg font-bold text-xl text-right text-primary placeholder:text-primary/10"
                                                            value={marks[student.id] || ""}
                                                            onChange={(e) => setMarks({ ...marks, [student.id]: e.target.value })}
                                                        />
                                                    </div>
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>

                    <div className="p-8 border-t border-border bg-muted/30 flex flex-col md:flex-row items-center justify-between gap-6 flex-shrink-0 relative">
                        <div className="flex items-center gap-3">
                            <div className="h-1.5 w-1.5 rounded-full bg-primary" />
                            <p className="text-[10px] font-mono font-bold uppercase tracking-widest text-muted-foreground">Total Students: {examStudents.length}</p>
                        </div>
                        <div className="flex items-center gap-x-6">
                            <Button 
                                variant="ghost"
                                onClick={() => setIsMarksOpen(false)}
                                className="text-[11px] font-bold uppercase tracking-widest text-muted-foreground"
                            >
                                Discard
                            </Button>
                            <Button 
                                onClick={handleSaveMarks}
                                disabled={loading}
                                className="h-12 px-10 bg-primary text-primary-foreground font-bold rounded-lg shadow-md uppercase tracking-wider text-[11px] hover:scale-105 transition-all"
                            >
                                {loading ? "Saving..." : "Save Marks"}
                            </Button>
                        </div>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "sonner";
import { saveMarks } from "@/app/actions/exams";
import { useRouter } from "next/navigation";
import { Save, FileDown, FileUp, Sparkles, BrainCircuit } from "lucide-react";
import { Badge } from "@/components/ui/badge";

const markSchema = z.object({
  marks: z.record(z.string(), z.union([z.coerce.number().min(0).max(100), z.literal("")])),
});

type MarkFormValues = {
  marks: Record<string, number | "">;
};

interface MarksEntryFormProps {
  examId: string;
  classId: string;
  subjectId: string;
  students: any[];
}

export function MarksEntryForm({
  examId,
  classId,
  subjectId,
  students,
}: MarksEntryFormProps) {
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  const form = useForm<MarkFormValues>({
    resolver: zodResolver(markSchema),
    defaultValues: {
      marks: (students || []).reduce(
        (acc, student) => ({
          ...acc,
          [student.id]: student.mark?.marks_obtained ?? "",
        }),
        {},
      ),
    },
  });

  async function onSubmit(values: MarkFormValues) {
    setLoading(true);
    try {
      const rows = Object.entries(values.marks)
        .filter(([_, mark]) => mark !== "")
        .map(([studentId, mark]) => ({
          exam_id: examId,
          student_id: studentId,
          subject_id: subjectId,
          marks_obtained: Number(mark),
        }));

      if (rows.length === 0) {
        toast.info("No marks to save");
        return;
      }

      const result = await saveMarks(rows);
      if (result.success) {
        toast.success("Marks recorded successfully for all students", {
          description: "Database synchronized via neural bridge.",
        });
        router.refresh();
      } else {
        toast.error(result.error || "Failed to sync marks");
      }
    } catch (error) {
      toast.error("An unexpected error occurred");
    } finally {
      setLoading(false);
    }
  }

  const handleExport = () => {
    toast.info("Generating CSV...", {
      description: "Preparing student roll numbers and current marks.",
    });
  };

  const handleImport = () => {
    toast.info("Awaiting CSV file...", {
      description: "Ready to parse bulk scores.",
    });
  };

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit(onSubmit)}
        className="space-y-6 animate-in fade-in duration-700"
      >
        <Card className="border-none glass futuristic-card overflow-hidden">
          <CardHeader className="bg-slate-50/30 flex flex-row items-center justify-between py-6 px-8">
            <div className="flex flex-col">
              <CardTitle className="text-xl font-black text-foreground">
                Performance Registry
              </CardTitle>
              <p className="text-[10px] uppercase tracking-widest font-bold text-muted-foreground mt-1">
                Bulk Score Entry Interface
              </p>
            </div>
            <div className="flex items-center gap-x-2">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={handleExport}
                className="hidden md:flex gap-x-2 rounded-xl border-border font-bold bg-white/50 backdrop-blur-sm"
              >
                <FileDown className="h-4 w-4" />
                Export
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={handleImport}
                className="hidden md:flex gap-x-2 rounded-xl border-border font-bold bg-white/50 backdrop-blur-sm"
              >
                <FileUp className="h-4 w-4" />
                Import
              </Button>
              <Button
                type="submit"
                disabled={loading}
                size="sm"
                className="gap-x-2 rounded-xl bg-card neon-blue font-bold px-6 py-5"
              >
                <Save className="h-4 w-4" />
                {loading ? "Syncing..." : "Sync All Nodes"}
              </Button>
            </div>
          </CardHeader>
          <CardContent className="p-0">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-slate-50/50 border-y border-border">
                    <th className="text-left py-4 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground">
                      Roll Node
                    </th>
                    <th className="text-left py-4 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground">
                      Subject Identity
                    </th>
                    <th className="text-center py-4 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground w-40">
                      Score (Max 100)
                    </th>
                    <th className="text-center py-4 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground">
                      System Status
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {students.map((student) => (
                    <tr
                      key={student.id}
                      className="hover:bg-slate-50/50 transition-colors group"
                    >
                      <td className="py-5 px-8">
                        <div className="flex flex-col">
                          <span className="font-bold text-foreground">
                            {student.roll_number || "SYS-0"}
                          </span>
                          <span className="text-[10px] text-muted-foreground font-mono">
                            ID: {student.id.slice(0, 8)}
                          </span>
                        </div>
                      </td>
                      <td className="py-5 px-8">
                        <div className="flex flex-col">
                          <span className="font-bold text-foreground group-hover:text-primary transition-colors">
                            {student.profile?.first_name}{" "}
                            {student.profile?.last_name}
                          </span>
                          <span className="text-[10px] text-muted-foreground font-medium tracking-tight">
                            Grade 10-A ΓÇó Physics Core
                          </span>
                        </div>
                      </td>
                      <td className="py-3 px-8">
                        <FormField
                          control={form.control}
                          name={`marks.${student.id}`}
                          render={({ field }) => (
                            <FormItem>
                              <FormControl>
                                <Input
                                  type="number"
                                  className="text-center bg-white border-2 border-border rounded-xl font-black text-lg focus-visible:ring-2 focus-visible:ring-blue-100 transition-all h-12"
                                  placeholder="00"
                                  {...field}
                                />
                              </FormControl>
                              <FormMessage className="text-[10px] font-bold text-red-500 mt-1" />
                            </FormItem>
                          )}
                        />
                      </td>
                      <td className="py-5 px-8 text-center">
                        {Number(form.watch(`marks.${student.id}`)) >= 40 ? (
                          <Badge className="bg-green-100 text-green-700 hover:bg-green-100 border-none px-3 font-black text-[10px] tracking-widest">
                            <Sparkles className="h-3 w-3 mr-1" />
                            PASS
                          </Badge>
                        ) : form.watch(`marks.${student.id}`) === "" ? (
                          <Badge
                            variant="outline"
                            className="border-border text-slate-300 font-bold text-[10px] tracking-widest"
                          >
                            PENDING
                          </Badge>
                        ) : (
                          <Badge className="bg-red-50 text-red-600 hover:bg-red-50 border-none px-3 font-black text-[10px] tracking-widest">
                            FAIL
                          </Badge>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      </form>
    </Form>
  );
}

"use client";

import { useState } from "react";
import {
    DollarSign,
    CreditCard,
    TrendingUp,
    Download,
    Plus,
    Search,
    Users,
    Briefcase,
    CheckCircle,
    Clock,
    AlertCircle,
    XCircle,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { createFee, recordPayment } from "@/app/actions/fees";
import { createPayroll, processPayroll, submitLeaveRequest, updateLeaveStatus } from "@/app/actions/payroll";
import { useRouter } from "next/navigation";
import { cn } from "@/lib/utils";

interface FeesDashboardProps {
    fees: any[];
    payments: any[];
    students: any[];
    classes: any[];
    staffPayrolls: any[];
    leaveRequests: any[];
    isStudent?: boolean;
    stats: {
        totalRevenue: number;
        outstanding: number;
        staffPayroll: number;
    };
}

export function FeesDashboard({
    fees,
    payments,
    students,
    classes,
    staffPayrolls,
    leaveRequests,
    isStudent = false,
    stats,
}: FeesDashboardProps) {
    const router = useRouter();
    const [search, setSearch] = useState("");
    const [isAddFeeOpen, setIsAddFeeOpen] = useState(false);
    const [isPaymentOpen, setIsPaymentOpen] = useState(false);
    const [loading, setLoading] = useState(false);

    // Fee form state
    const [feeForm, setFeeForm] = useState({
        name: "",
        amount: "",
        due_date: "",
        class_id: "",
        fee_type: "tuition",
        description: "",
    });

    // Payment form state
    const [payForm, setPayForm] = useState({
        student_id: "",
        fee_id: "",
        amount_paid: "",
        payment_method: "cash",
    });

    const handleCreateFee = async () => {
        setLoading(true);
        const result = await createFee({
            ...feeForm,
            amount: parseFloat(feeForm.amount),
            class_id: feeForm.class_id || undefined,
        });
        setLoading(false);
        if (result.success) {
            setIsAddFeeOpen(false);
            setFeeForm({ name: "", amount: "", due_date: "", class_id: "", fee_type: "tuition", description: "" });
            router.refresh();
        }
    };

    const handleRecordPayment = async () => {
        setLoading(true);
        const result = await recordPayment({
            ...payForm,
            amount_paid: parseFloat(payForm.amount_paid),
        });
        setLoading(false);
        if (result.success) {
            setIsPaymentOpen(false);
            setPayForm({ student_id: "", fee_id: "", amount_paid: "", payment_method: "cash" });
            router.refresh();
        }
    };

    return (
        <div className="space-y-12 animate-in fade-in transition-all duration-1000">
            {/* Action Bar */}
            {!isStudent && (
                <div className="flex items-center justify-end gap-4 mb-10 border-b border-border pb-8">
                    <Dialog open={isPaymentOpen} onOpenChange={setIsPaymentOpen}>
                        <DialogTrigger asChild>
                            <Button variant="outline" className="h-12 px-8 bg-secondary border border-border text-primary font-bold rounded-lg transition-all uppercase tracking-widest text-[9px] hover:bg-primary hover:text-primary-foreground group">
                                Record Payment
                                <CreditCard className="ml-2 h-4 w-4 group-hover:animate-bounce" />
                            </Button>
                        </DialogTrigger>
                        <DialogContent className="bg-card border-border p-0 overflow-hidden max-w-xl rounded-xl">
                            <div className="p-6 border-b border-border bg-secondary/30">
                                <h3 className="text-2xl font-black italic uppercase tracking-tighter text-foreground">Record <span className="text-primary">Payment</span></h3>
                                <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground mt-2 italic">Manual Payment Entry</p>
                            </div>
                            <div className="p-8 space-y-6">
                                <div className="space-y-2">
                                    <Label className="text-[10px] font-bold uppercase tracking-widest text-primary italic">Student</Label>
                                    <Select value={payForm.student_id} onValueChange={(v) => setPayForm({ ...payForm, student_id: v })}>
                                        <SelectTrigger className="bg-background border-border h-12 font-bold text-xs uppercase italic"><SelectValue placeholder="Select Student" /></SelectTrigger>
                                        <SelectContent>
                                            {students.map((s) => (
                                                <SelectItem key={s.id} value={s.id} className="font-bold text-[10px] uppercase italic">{s.profile?.full_name} ({s.admission_number})</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div className="space-y-2">
                                    <Label className="text-[10px] font-bold uppercase tracking-widest text-primary italic">Fee Structure</Label>
                                    <Select value={payForm.fee_id} onValueChange={(v) => setPayForm({ ...payForm, fee_id: v })}>
                                        <SelectTrigger className="bg-background border-border h-12 font-bold text-xs uppercase italic"><SelectValue placeholder="Select Fee" /></SelectTrigger>
                                        <SelectContent>
                                            {fees.map((f) => (
                                                <SelectItem key={f.id} value={f.id} className="font-bold text-[10px] uppercase italic">{f.name} ΓÇö Γé╣{f.amount}</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div className="grid grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-bold uppercase tracking-widest text-primary italic">Amount (Γé╣)</Label>
                                        <Input type="number" value={payForm.amount_paid} onChange={(e) => setPayForm({ ...payForm, amount_paid: e.target.value })} className="bg-background border-border h-12 font-bold text-sm italic" placeholder="0.00" />
                                    </div>
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-bold uppercase tracking-widest text-primary italic">Payment Method</Label>
                                        <Select value={payForm.payment_method} onValueChange={(v) => setPayForm({ ...payForm, payment_method: v })}>
                                            <SelectTrigger className="bg-background border-border h-12 font-bold text-xs uppercase italic"><SelectValue /></SelectTrigger>
                                            <SelectContent>
                                                {["cash", "card", "upi", "bank_transfer", "cheque", "online"].map((m) => (
                                                    <SelectItem key={m} value={m} className="font-bold text-[10px] uppercase italic">{m.toUpperCase()}</SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                </div>
                                <Button onClick={handleRecordPayment} disabled={loading} className="w-full h-14 bg-primary text-primary-foreground font-black uppercase tracking-widest text-[11px] shadow-sm transition-all hover:scale-[1.02] rounded-lg">
                                    {loading ? "PROCESSING..." : "RECORD PAYMENT"}
                                </Button>
                            </div>
                        </DialogContent>
                    </Dialog>

                    <Dialog open={isAddFeeOpen} onOpenChange={setIsAddFeeOpen}>
                        <DialogTrigger asChild>
                            <Button className="h-12 px-8 bg-primary text-primary-foreground font-bold rounded-lg shadow-sm uppercase tracking-widest text-[9px] transition-all hover:scale-105">
                                Add New Fee
                                <Plus className="ml-2 h-4 w-4" />
                            </Button>
                        </DialogTrigger>
                        <DialogContent className="bg-card border-border p-0 overflow-hidden max-w-xl rounded-xl">
                            <div className="p-6 border-b border-border bg-secondary/30">
                                <h3 className="text-2xl font-black italic uppercase tracking-tighter text-foreground">Create <span className="text-primary">Fee</span> Structure</h3>
                                <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground mt-2 italic">Fee Schema Definition</p>
                            </div>
                            <div className="p-8 space-y-6">
                                <div className="space-y-2">
                                    <Label className="text-[10px] font-bold uppercase tracking-widest text-primary italic">Fee Name</Label>
                                    <Input value={feeForm.name} onChange={(e) => setFeeForm({ ...feeForm, name: e.target.value })} className="bg-background border-border h-12 font-bold text-sm italic focus-visible:ring-primary/50" placeholder="e.g. Annual Tuition Fee" />
                                </div>
                                <div className="grid grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-bold uppercase tracking-widest text-primary italic">Amount (Γé╣)</Label>
                                        <Input type="number" value={feeForm.amount} onChange={(e) => setFeeForm({ ...feeForm, amount: e.target.value })} className="bg-background border-border h-12 font-bold text-sm italic focus-visible:ring-primary/50" placeholder="0.00" />
                                    </div>
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-bold uppercase tracking-widest text-primary italic">Due Date</Label>
                                        <Input type="date" value={feeForm.due_date} onChange={(e) => setFeeForm({ ...feeForm, due_date: e.target.value })} className="bg-background border-border h-12 font-bold text-sm italic focus-visible:ring-primary/50" />
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-bold uppercase tracking-widest text-primary italic">Target Class</Label>
                                        <Select value={feeForm.class_id} onValueChange={(v) => setFeeForm({ ...feeForm, class_id: v })}>
                                            <SelectTrigger className="bg-background border-border h-12 font-bold text-xs uppercase italic focus:ring-primary/50"><SelectValue placeholder="All Classes" /></SelectTrigger>
                                            <SelectContent>
                                                {classes.map((c) => (
                                                    <SelectItem key={c.id} value={c.id} className="font-bold text-[10px] uppercase italic">{c.name}</SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-bold uppercase tracking-widest text-primary italic">Category</Label>
                                        <Select value={feeForm.fee_type} onValueChange={(v) => setFeeForm({ ...feeForm, fee_type: v })}>
                                            <SelectTrigger className="bg-background border-border h-12 font-bold text-xs uppercase italic focus:ring-primary/50"><SelectValue /></SelectTrigger>
                                            <SelectContent>
                                                {["tuition", "transport", "library", "lab", "sports", "other"].map((t) => (
                                                    <SelectItem key={t} value={t} className="font-bold text-[10px] uppercase italic">{t.toUpperCase()}</SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                </div>
                                <Button onClick={handleCreateFee} disabled={loading} className="w-full h-14 bg-primary text-primary-foreground font-black uppercase tracking-widest text-[11px] shadow-sm transition-all hover:scale-[1.02] rounded-lg">
                                    {loading ? "CREATING..." : "CREATE FEE STRUCTURE"}
                                </Button>
                            </div>
                        </DialogContent>
                    </Dialog>
                </div>
            )}

            {/* Metric Grid */}
            <div className="grid gap-10 lg:grid-cols-3">
                <div className="bg-card border border-border p-8 rounded-xl relative overflow-hidden group transition-all duration-300 shadow-sm">
                    <div className="absolute top-0 right-0 p-8 opacity-[0.05] group-hover:scale-110 transition-transform duration-700">
                        <TrendingUp className="h-32 w-32 text-primary" />
                    </div>
                    <p className="text-[10px] font-bold uppercase tracking-widest text-primary mb-6 italic">Total Revenue</p>
                    <div className="relative z-10 flex items-baseline gap-x-3">
                        <h3 className="text-6xl font-black italic tracking-tighter text-foreground leading-none">
                            Γé╣{stats.totalRevenue.toLocaleString()}
                        </h3>
                        <Badge className="bg-primary/10 text-primary border border-primary/20 font-bold text-[8px] uppercase tracking-widest italic">+14%</Badge>
                    </div>
                    <div className="h-2 w-full bg-secondary rounded-full mt-8 overflow-hidden">
                        <div className="h-full bg-primary transition-all duration-1000" style={{ width: '82%' }} />
                    </div>
                    <p className="text-[9px] font-bold uppercase tracking-widest text-muted-foreground/40 mt-3 italic">Finalized Collection</p>
                </div>

                <div className="bg-card border border-border p-8 rounded-xl relative overflow-hidden group transition-all duration-300 shadow-sm hover:border-red-500/40">
                    <p className="text-[10px] font-bold uppercase tracking-widest text-red-500 mb-6 italic">Outstanding Invoices</p>
                    <div className="relative z-10 flex items-baseline gap-x-3">
                        <h3 className="text-6xl font-black italic tracking-tighter text-foreground leading-none">
                            Γé╣{stats.outstanding.toLocaleString()}
                        </h3>
                    </div>
                    <div className="h-2 w-full bg-secondary rounded-full mt-8 overflow-hidden">
                        <div className="h-full bg-red-500 transition-all duration-1000" style={{ width: `${Math.min(100, (stats.outstanding / stats.totalRevenue) * 100)}%` }} />
                    </div>
                    <p className="text-[9px] font-bold uppercase tracking-widest text-muted-foreground/40 mt-3 italic">Pending Payments</p>
                </div>

                <div className="bg-card border border-border p-8 rounded-xl relative overflow-hidden group transition-all duration-300 shadow-sm">
                    <p className="text-[10px] font-bold uppercase tracking-widest text-primary mb-6 italic">Staff Payroll</p>
                    <div className="relative z-10 flex items-baseline gap-x-3">
                        <h3 className="text-6xl font-black italic tracking-tighter text-foreground leading-none">
                            Γé╣{stats.staffPayroll.toLocaleString()}
                        </h3>
                    </div>
                    <div className="h-2 w-full bg-secondary rounded-full mt-8 overflow-hidden text-center flex items-center justify-center">
                        <TrendingUp className="h-3 w-3 text-primary mr-2" />
                        <span className="text-[8px] font-bold uppercase tracking-widest text-primary">Monthly Outflow</span>
                    </div>
                    <p className="text-[9px] font-bold uppercase tracking-widest text-muted-foreground/40 mt-3 italic">Institutional Expenses</p>
                </div>
            </div>

            <Tabs defaultValue="fees" className="space-y-10">
                <div className="flex items-center justify-between border-b border-border pb-6">
                    <TabsList className="bg-secondary/30 border border-border p-1 rounded-xl h-12 w-fit">
                        <TabsTrigger
                            value="fees"
                            className="rounded-lg px-8 py-2 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground font-bold uppercase tracking-widest text-[10px] transition-all gap-x-2"
                        >
                            <DollarSign className="h-3.5 w-3.5" />
                            Fee Overview
                        </TabsTrigger>
                        <TabsTrigger
                            value="payments"
                            className="rounded-lg px-8 py-2 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground font-bold uppercase tracking-widest text-[10px] transition-all gap-x-2"
                        >
                            <CreditCard className="h-3.5 w-3.5" />
                            Transaction History
                        </TabsTrigger>
                        {!isStudent && (
                            <TabsTrigger
                                value="payroll"
                                className="rounded-lg px-8 py-2 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground font-bold uppercase tracking-widest text-[10px] transition-all gap-x-2"
                            >
                                <Briefcase className="h-3.5 w-3.5" />
                                Staff Payroll
                            </TabsTrigger>
                        )}
                    </TabsList>
                </div>

                <TabsContent value="fees" className="outline-none">
                    <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                        <table className="w-full text-left">
                            <thead className="bg-secondary/50">
                                <tr>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Fee Name</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Category</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Amount</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Due Date</th>
                                    <th className="px-8 py-5 text-right text-[10px] font-bold uppercase tracking-widest text-primary italic">Target Class</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-border">
                                {fees.map((fee) => (
                                    <tr key={fee.id} className="group hover:bg-secondary/20 transition-all duration-300">
                                        <td className="px-8 py-5 font-bold text-foreground uppercase italic tracking-tight text-xs group-hover:text-primary transition-colors">{fee.name}</td>
                                        <td className="px-8 py-5">
                                            <Badge variant="outline" className="text-[8px] font-bold tracking-widest uppercase border-primary/20 text-primary bg-primary/5 px-3 py-1 rounded-lg italic">{fee.fee_type}</Badge>
                                        </td>
                                        <td className="px-8 py-5 font-bold text-foreground text-sm italic tracking-tighter group-hover:translate-x-1 transition-transform">Γé╣{fee.amount.toLocaleString()}</td>
                                        <td className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-muted-foreground/60 italic">{fee.due_date}</td>
                                        <td className="px-8 py-5 text-right text-[10px] font-bold uppercase tracking-widest text-muted-foreground/40 italic">{fee.class?.name || "General"}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </TabsContent>

                <TabsContent value="payments" className="outline-none">
                   <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                        <table className="w-full text-left">
                            <thead className="bg-secondary/50">
                                <tr>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Student</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Amount</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Method</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Status</th>
                                    <th className="px-8 py-5 text-right text-[10px] font-bold uppercase tracking-widest text-primary italic">Receipt ID</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-border">
                                {payments.map((p) => (
                                    <tr key={p.id} className="group hover:bg-secondary/20 transition-all duration-300">
                                        <td className="px-8 py-5">
                                            <div className="flex flex-col">
                                                <span className="font-bold text-foreground uppercase italic tracking-tight text-xs group-hover:text-primary transition-colors">{p.student?.profile?.full_name}</span>
                                                <span className="text-[8px] font-bold uppercase tracking-widest text-muted-foreground/40 mt-1 italic">{p.student?.admission_number}</span>
                                            </div>
                                        </td>
                                        <td className="px-8 py-5 font-bold text-foreground text-sm italic tracking-tighter">Γé╣{p.amount_paid.toLocaleString()}</td>
                                        <td className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">{p.payment_method}</td>
                                        <td className="px-8 py-5">
                                            <Badge className={cn(
                                                "text-[8px] font-bold tracking-widest uppercase rounded-lg px-3 py-1",
                                                p.status === "completed" ? "bg-emerald-500 text-white shadow-sm" : "bg-red-500 text-white"
                                            )}>
                                                {p.status}
                                            </Badge>
                                        </td>
                                        <td className="px-8 py-5 text-right text-[10px] font-bold uppercase tracking-widest text-muted-foreground/20 italic">{p.receipt_number || "PENDING"}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </TabsContent>
                
                <TabsContent value="payroll" className="outline-none">
                    <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                        <table className="w-full text-left">
                            <thead className="bg-secondary/50">
                                <tr>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Faculty Name</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Base Salary</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Incentives</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Deductions</th>
                                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-primary italic">Month/Year</th>
                                    <th className="px-8 py-5 text-right text-[10px] font-bold uppercase tracking-widest text-primary italic">Status</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-border">
                                {staffPayrolls.map((p) => (
                                    <tr key={p.id} className="group hover:bg-secondary/20 transition-all duration-300">
                                        <td className="px-8 py-5">
                                            <div className="flex flex-col">
                                                <span className="font-bold text-foreground uppercase italic tracking-tight text-xs group-hover:text-primary transition-colors">
                                                    {p.staff?.first_name} {p.staff?.last_name}
                                                </span>
                                                <span className="text-[8px] font-bold uppercase tracking-widest text-muted-foreground/40 mt-1 italic">{p.staff?.employee_id || "STAFF-ID"}</span>
                                            </div>
                                        </td>
                                        <td className="px-8 py-5 font-bold text-foreground text-sm italic tracking-tighter transition-transform group-hover:translate-x-1">Γé╣{p.base_salary.toLocaleString()}</td>
                                        <td className="px-8 py-5 text-emerald-500 font-bold text-xs italic tracking-tighter">+Γé╣{(p.bonuses || 0).toLocaleString()}</td>
                                        <td className="px-8 py-5 text-red-500 font-bold text-xs italic tracking-tighter">-Γé╣{(p.deductions || 0).toLocaleString()}</td>
                                        <td className="px-8 py-5 text-[10px] font-bold uppercase tracking-widest text-muted-foreground/60 italic">{p.month}/{p.year}</td>
                                        <td className="px-8 py-5 text-right">
                                            <Badge className={cn(
                                                "text-[8px] font-bold tracking-widest uppercase rounded-lg px-3 py-1",
                                                p.status === "paid" ? "bg-emerald-500 text-white shadow-sm" : "bg-yellow-500 text-white"
                                            )}>
                                                {p.status}
                                            </Badge>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </TabsContent>
            </Tabs>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Heart, Plus, Thermometer, Pill, AlertTriangle, Clock, CheckCircle } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { createInfirmaryLog, dischargeFromInfirmary } from "@/app/actions/health";
import { useRouter } from "next/navigation";
import { cn } from "@/lib/utils";

interface HealthDashboardProps {
    infirmaryLogs: any[];
    healthProfiles: any[];
    students: any[];
    userRole?: string | null;
}

export function HealthDashboard({ infirmaryLogs, healthProfiles, students, userRole }: HealthDashboardProps) {
    const isAdminOrTeacher = userRole === "admin" || userRole === "teacher";
    const router = useRouter();
    const [isLogOpen, setIsLogOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [logForm, setLogForm] = useState({ student_id: "", visit_reason: "", symptoms: "", treatment_provided: "", medication_given: "", temperature: "" });

    const handleCreateLog = async () => {
        setLoading(true);
        await createInfirmaryLog({ ...logForm, temperature: logForm.temperature ? parseFloat(logForm.temperature) : undefined });
        setLoading(false);
        setIsLogOpen(false);
        setLogForm({ student_id: "", visit_reason: "", symptoms: "", treatment_provided: "", medication_given: "", temperature: "" });
        router.refresh();
    };

    const handleDischarge = async (id: string) => {
        setLoading(true);
        await dischargeFromInfirmary(id);
        setLoading(false);
        router.refresh();
    };

    const activeVisits = infirmaryLogs.filter(l => l.status === "under_observation");

    return (
        <div className="space-y-8 animate-in fade-in duration-700">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-4xl font-black tracking-tighter text-foreground uppercase italic underline decoration-primary/30 underline-offset-8">
                        Medical Infrastructure
                    </h2>
                    <p className="text-primary font-black uppercase text-[10px] tracking-[0.3em] mt-3 bg-primary/10 w-fit px-3 py-1 rounded-sm border border-primary/20">
                        Bio-Metric Health Records & Institutional Infirmary Protocols
                    </p>
                </div>
                {isAdminOrTeacher && (
                    <div className="flex gap-x-3">
                        <Badge variant="outline" className="rounded-sm px-4 py-1.5 border-destructive/20 text-destructive bg-destructive/5 gap-x-2 font-black uppercase text-[10px] tracking-widest shadow-lg">
                            <AlertTriangle className="h-3 w-3" /> {activeVisits.length} ACTIVE OBSERVATION NODES
                        </Badge>
                        <Dialog open={isLogOpen} onOpenChange={setIsLogOpen}>
                            <DialogTrigger asChild>
                                <Button className="rounded-2xl bg-card text-white font-bold gap-x-2 neon-blue"><Plus className="h-4 w-4" /> Record Visit</Button>
                            </DialogTrigger>
                            <DialogContent className="glass border-none max-w-lg">
                                <DialogHeader><DialogTitle className="font-black text-2xl">Infirmary Visit</DialogTitle></DialogHeader>
                                <div className="space-y-4 pt-4">
                                    <div className="space-y-2">
                                        <Label className="text-xs font-bold uppercase text-muted-foreground">Student</Label>
                                        <Select value={logForm.student_id} onValueChange={(v) => setLogForm({ ...logForm, student_id: v })}>
                                            <SelectTrigger><SelectValue placeholder="Select student" /></SelectTrigger>
                                            <SelectContent>{students.map(s => <SelectItem key={s.id} value={s.id}>{s.profile?.first_name} {s.profile?.last_name}</SelectItem>)}</SelectContent>
                                        </Select>
                                    </div>
                                    <div className="space-y-2">
                                        <Label className="text-xs font-bold uppercase text-muted-foreground">Reason</Label>
                                        <Input value={logForm.visit_reason} onChange={(e) => setLogForm({ ...logForm, visit_reason: e.target.value })} placeholder="Headache, fever, injury..." />
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <Label className="text-xs font-bold uppercase text-muted-foreground">Symptoms</Label>
                                            <Input value={logForm.symptoms} onChange={(e) => setLogForm({ ...logForm, symptoms: e.target.value })} placeholder="Describe symptoms" />
                                        </div>
                                        <div className="space-y-2">
                                            <Label className="text-xs font-bold uppercase text-muted-foreground">Temperature (┬░F)</Label>
                                            <Input type="number" step="0.1" value={logForm.temperature} onChange={(e) => setLogForm({ ...logForm, temperature: e.target.value })} placeholder="98.6" />
                                        </div>
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <Label className="text-xs font-bold uppercase text-muted-foreground">Treatment</Label>
                                            <Input value={logForm.treatment_provided} onChange={(e) => setLogForm({ ...logForm, treatment_provided: e.target.value })} placeholder="Rest, ice pack..." />
                                        </div>
                                        <div className="space-y-2">
                                            <Label className="text-xs font-bold uppercase text-muted-foreground">Medication</Label>
                                            <Input value={logForm.medication_given} onChange={(e) => setLogForm({ ...logForm, medication_given: e.target.value })} placeholder="Paracetamol 500mg" />
                                        </div>
                                    </div>
                                    <Button onClick={handleCreateLog} disabled={loading} className="w-full rounded-xl py-6 bg-card text-white font-bold">
                                        {loading ? "Recording..." : "Record Visit"}
                                    </Button>
                                </div>
                            </DialogContent>
                        </Dialog>
                    </div>
                )}
            </div>

            {/* Stats */}
            <div className="grid gap-6 md:grid-cols-3">
                <Card className="border-border bg-card/40 backdrop-blur-xl rounded-sm p-8 shadow-2xl group hover:border-primary transition-all">
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] text-foreground/40 mb-2 italic">Total Clinical Visits</p>
                    <h3 className="text-4xl font-black text-foreground tracking-tighter italic underline decoration-primary/20 underline-offset-4">{infirmaryLogs.length}</h3>
                </Card>
                <Card className="border-destructive/20 bg-destructive/5 backdrop-blur-xl rounded-sm p-8 shadow-2xl relative overflow-hidden group">
                    <Heart className="absolute right-[-10px] bottom-[-10px] h-24 w-24 text-destructive/10 group-hover:text-destructive transition-all" />
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] text-destructive mb-2 italic">Current Observation</p>
                    <h3 className="text-4xl font-black text-foreground tracking-tighter italic">{activeVisits.length}</h3>
                </Card>
                <Card className="border-border bg-card/40 backdrop-blur-xl rounded-sm p-8 shadow-2xl group hover:border-primary transition-all">
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] text-foreground/40 mb-2 italic">Active Bio-Profiles</p>
                    <h3 className="text-4xl font-black text-foreground tracking-tighter italic">{healthProfiles.length}</h3>
                </Card>
            </div>

            {/* Infirmary Logs */}
            <div className="bg-white/40 backdrop-blur-md rounded-3xl border border-white/20 overflow-hidden shadow-2xl">
                <table className="w-full text-sm">
                    <thead className="bg-slate-50/50">
                        <tr className="border-b">
                            <th className="text-left py-5 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground">Student</th>
                            <th className="text-left py-5 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground">Reason</th>
                            <th className="text-left py-5 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground">Temp</th>
                            <th className="text-left py-5 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground">Treatment</th>
                            <th className="text-left py-5 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground">Status</th>
                            <th className="text-right py-5 px-8 font-black uppercase tracking-widest text-[10px] text-muted-foreground">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y">
                        {infirmaryLogs.length === 0 ? (
                            <tr><td colSpan={6} className="py-12 text-center text-muted-foreground font-medium">No infirmary visits recorded yet.</td></tr>
                        ) : (
                            infirmaryLogs.map((log) => (
                                <tr key={log.id} className="hover:bg-white/60 transition-colors">
                                    <td className="py-6 px-8 flex items-center gap-x-6 group">
                                        <div className="h-12 w-12 rounded-sm bg-destructive/10 text-destructive flex items-center justify-center font-black border border-destructive/20 transition-all group-hover:bg-destructive group-hover:text-white shadow-md">
                                            <Heart className="h-6 w-6" />
                                        </div>
                                        <div>
                                            <p className="font-black text-foreground uppercase tracking-tight italic group-hover:text-primary transition-colors">{log.student?.profile?.first_name} {log.student?.profile?.last_name}</p>
                                            <p className="text-[9px] font-black text-foreground/40 uppercase tracking-widest mt-0.5">ID: {log.student?.admission_number}</p>
                                        </div>
                                    </td>
                                    <td className="py-6 px-8 text-foreground font-black uppercase text-xs tracking-tight">{log.visit_reason}</td>
                                    <td className="py-6 px-8 font-mono text-[11px] font-black text-primary p-2 bg-primary/5 rounded-sm w-fit border border-primary/10">{log.temperature ? `${log.temperature}┬░F` : "ΓÇö"}</td>
                                    <td className="py-6 px-8 text-foreground/60 text-[10px] font-bold uppercase tracking-widest">{log.treatment_provided || "ΓÇö"}</td>
                                    <td className="py-6 px-8">
                                        <Badge variant="outline" className={cn("font-black text-[10px] px-3 py-1 rounded-sm uppercase tracking-[0.2em] shadow-lg",
                                            log.status === "under_observation" ? "bg-destructive text-destructive border-destructive/20 shadow-destructive/10" :
                                                log.status === "discharged" ? "bg-primary text-primary-foreground emerald-glow border-primary/20" :
                                                    "bg-foreground/5 text-foreground border-border"
                                        )}>
                                            {log.status?.replace("_", " ").toUpperCase()}
                                        </Badge>
                                    </td>
                                    <td className="py-6 px-8 text-right">
                                        {isAdminOrTeacher && log.status === "under_observation" && (
                                            <Button size="sm" variant="ghost" onClick={() => handleDischarge(log.id)} className="rounded-xl font-bold text-xs text-green-500 hover:bg-green-50">
                                                <CheckCircle className="h-4 w-4 mr-1" /> DISCHARGE
                                            </Button>
                                        )}
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import {
    Library,
    Book,
    Search,
    Plus,
    Package,
    ArrowRightLeft,
    AlertTriangle,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { createBook, issueBook, returnBook } from "@/app/actions/library";
import { createInventoryItem } from "@/app/actions/modules";
import { useRouter } from "next/navigation";

interface LibraryDashboardProps {
    books: any[];
    transactions: any[];
    students: any[];
    inventoryItems: any[];
    userRole?: string | null;
}

export function LibraryDashboard({ books, transactions, students, inventoryItems, userRole }: LibraryDashboardProps) {
    const isStaff = userRole === "admin" || userRole === "teacher";
    const router = useRouter();
    const [search, setSearch] = useState("");
    const [isAddBookOpen, setIsAddBookOpen] = useState(false);
    const [isIssueOpen, setIsIssueOpen] = useState(false);
    const [loading, setLoading] = useState(false);

    const [bookForm, setBookForm] = useState({ title: "", author: "", isbn: "", category: "", total_copies: "1", shelf_location: "" });
    const [issueForm, setIssueForm] = useState({ book_id: "", student_id: "", due_date: "" });

    const handleCreateBook = async () => {
        setLoading(true);
        const result = await createBook({ ...bookForm, total_copies: parseInt(bookForm.total_copies) || 1 });
        setLoading(false);
        if (result.success) {
            setIsAddBookOpen(false);
            setBookForm({ title: "", author: "", isbn: "", category: "", total_copies: "1", shelf_location: "" });
            router.refresh();
        }
    };

    const handleIssueBook = async () => {
        setLoading(true);
        const result = await issueBook(issueForm);
        setLoading(false);
        if (result.success) {
            setIsIssueOpen(false);
            setIssueForm({ book_id: "", student_id: "", due_date: "" });
            router.refresh();
        }
    };

    const handleReturn = async (txId: string) => {
        setLoading(true);
        await returnBook(txId);
        setLoading(false);
        router.refresh();
    };

    const filteredBooks = books.filter(
        (b) => (b.title?.toLowerCase() || "").includes(search.toLowerCase()) || (b.author?.toLowerCase() || "").includes(search.toLowerCase())
    );

    return (
        <div className="space-y-12 animate-in fade-in transition-all duration-1000 relative reveal-1">
            {/* Background Mesh */}
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_0%,rgba(16,185,129,0.05),transparent_70%)] pointer-events-none" />

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 border-b border-primary/10 pb-12 relative z-10">
                <div className="flex items-center gap-x-8">
                    <div className="h-20 w-20 bg-primary/10 border border-primary/20 flex items-center justify-center text-primary shadow-[0_0_40px_rgba(16,185,129,0.15)] skew-x-[-12deg] group hover:bg-primary hover:text-primary-foreground transition-all duration-700">
                        <Library className="h-10 w-10 skew-x-[12deg] transition-all duration-700" />
                    </div>
                    <div>
                        <div className="relative">
                            <h2 className="text-5xl font-black italic uppercase tracking-tighter text-foreground leading-none">
                                Library <span className="text-primary italic">& Inventory</span>
                            </h2>
                            <div className="absolute -bottom-2 left-0 w-24 h-1 bg-primary/40 skew-x-[-24deg]" />
                        </div>
                        <p className="text-[10px] font-mono font-black uppercase tracking-[0.5em] text-foreground/30 mt-4 italic flex items-center gap-2">
                            <span className="h-1 w-1 rounded-full bg-primary animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.8)]" /> 
                            Library Management & School Inventory Tracking
                        </p>
                    </div>
                </div>

                {isStaff && (
                    <div className="flex gap-x-4 skew-x-[-12deg]">
                        <Dialog open={isIssueOpen} onOpenChange={setIsIssueOpen}>
                            <DialogTrigger asChild>
                                <Button variant="outline" className="h-16 px-10 rounded-none border-primary/20 bg-primary/5 hover:bg-primary/10 text-primary uppercase font-black tracking-[0.2em] text-[11px] transition-all group">
                                    <span className="not-skew-x flex items-center gap-3">
                                        <ArrowRightLeft className="h-4 w-4 group-hover:rotate-180 transition-transform duration-500" /> ISSUE BOOK
                                    </span>
                                </Button>
                            </DialogTrigger>
                            <DialogContent className="p-0 border-none bg-transparent skew-x-[-12deg] max-w-2xl overflow-visible">
                                <div className="relative glass-panel border-primary/20 p-12 shadow-[0_0_100px_rgba(16,185,129,0.1)] overflow-hidden">
                                    <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 blur-3xl -mr-16 -mt-16" />
                                    
                                    <div className="not-skew-x relative z-10">
                                        <div className="not-skew-x flex justify-between items-start mb-10">
                                            <div>
                                                <DialogTitle className="font-black italic text-4xl uppercase tracking-tighter text-foreground leading-none">
                                                    Issue <span className="text-primary italic">Book</span>
                                                </DialogTitle>
                                                <div className="h-1 w-20 bg-primary/40 mt-4 skew-x-[-24deg]" />
                                                <p className="text-[10px] font-mono font-black text-primary/60 uppercase tracking-[0.4em] mt-6 italic">Assign a book to a student profile</p>
                                            </div>
                                            <Button variant="ghost" size="icon" onClick={() => setIsIssueOpen(false)} className="text-primary/40 hover:text-primary hover:bg-primary/10 -mt-4 -mr-4 rounded-none">
                                                <Plus className="h-6 w-6 rotate-45" />
                                            </Button>
                                        </div>

                                        <div className="space-y-8">
                                            <div className="space-y-3">
                                                <Label className="text-[9px] font-mono font-black uppercase text-foreground/40 tracking-[0.3em] flex items-center gap-2 italic">
                                                    <span className="h-1.5 w-1.5 rounded-full bg-primary/40" /> SELECT BOOK
                                                </Label>
                                                <Select value={issueForm.book_id} onValueChange={(v) => setIssueForm({ ...issueForm, book_id: v })}>
                                                    <SelectTrigger className="h-14 rounded-none bg-background/50 border-primary/10 hover:border-primary/40 focus:ring-primary/20 font-mono font-black uppercase text-[11px] tracking-widest transition-all">
                                                        <SelectValue placeholder="SELECT_VOID" />
                                                    </SelectTrigger>
                                                    <SelectContent className="bg-card border-primary/20 rounded-none shadow-2xl">
                                                        {books.filter(b => b.available_copies > 0).map(b => (
                                                            <SelectItem key={b.id} value={b.id} className="font-mono font-black uppercase text-[10px] tracking-widest focus:bg-primary focus:text-primary-foreground italic py-3 cursor-pointer">
                                                                {b.title} [AVAIL: {b.available_copies}]
                                                            </SelectItem>
                                                        ))}
                                                    </SelectContent>
                                                </Select>
                                            </div>

                                            <div className="space-y-3">
                                                <Label className="text-[9px] font-mono font-black uppercase text-foreground/40 tracking-[0.3em] flex items-center gap-2 italic">
                                                    <span className="h-1.5 w-1.5 rounded-full bg-primary/40" /> SELECT STUDENT
                                                </Label>
                                                <Select value={issueForm.student_id} onValueChange={(v) => setIssueForm({ ...issueForm, student_id: v })}>
                                                    <SelectTrigger className="h-14 rounded-none bg-background/50 border-primary/10 hover:border-primary/40 focus:ring-primary/20 font-mono font-black uppercase text-[11px] tracking-widest transition-all">
                                                        <SelectValue placeholder="SELECT_VOID" />
                                                    </SelectTrigger>
                                                    <SelectContent className="bg-card border-primary/20 rounded-none shadow-2xl">
                                                        {students.map(s => (
                                                            <SelectItem key={s.id} value={s.id} className="font-mono font-black uppercase text-[10px] tracking-widest focus:bg-primary focus:text-primary-foreground italic py-3 cursor-pointer">
                                                                {s.profile?.full_name} [ID: {s.admission_number}]
                                                            </SelectItem>
                                                        ))}
                                                    </SelectContent>
                                                </Select>
                                            </div>

                                            <div className="space-y-3 pb-4">
                                                <Label className="text-[9px] font-mono font-black uppercase text-foreground/40 tracking-[0.3em] flex items-center gap-2 italic">
                                                    <span className="h-1.5 w-1.5 rounded-full bg-primary/40" /> DUE DATE
                                                </Label>
                                                <Input type="date" value={issueForm.due_date} onChange={(e) => setIssueForm({ ...issueForm, due_date: e.target.value })} className="h-14 rounded-none bg-background/50 border-primary/10 hover:border-primary/40 font-mono font-black text-xs transition-all" />
                                            </div>

                                            <Button onClick={handleIssueBook} disabled={loading} className="w-full h-18 rounded-none bg-primary text-primary-foreground font-black italic uppercase tracking-[0.3em] shadow-[0_0_30px_rgba(16,185,129,0.3)] hover:scale-[1.02] active:scale-95 transition-all text-xs border border-primary/20 gap-3">
                                                {loading ? "PROCESSING..." : "CONFIRM ISSUE"}
                                            </Button>
                                        </div>
                                    </div>

                                    {/* Collection Label */}
                                    <div className="absolute -left-12 -bottom-10 opacity-[0.03] font-mono text-[100px] font-black italic text-primary pointer-events-none uppercase">DEPLOY</div>
                                </div>
                            </DialogContent>
                        </Dialog>

                        <Dialog open={isAddBookOpen} onOpenChange={setIsAddBookOpen}>
                            <DialogTrigger asChild>
                                <Button className="h-16 px-10 rounded-none bg-primary text-primary-foreground font-black uppercase tracking-[0.2em] text-[11px] emerald-glow shadow-2xl hover:scale-105 transition-all group">
                                    <span className="not-skew-x flex items-center gap-3">
                                        <Plus className="h-4 w-4 group-hover:rotate-90 transition-transform" /> ADD NEW BOOK
                                    </span>
                                </Button>
                            </DialogTrigger>
                            <DialogContent className="p-0 border-none bg-transparent skew-x-[-12deg] max-w-2xl overflow-visible">
                                <div className="relative glass-panel border-primary/20 p-12 shadow-[0_0_100px_rgba(16,185,129,0.1)] overflow-hidden">
                                    <div className="absolute top-0 left-0 w-32 h-32 bg-primary/10 blur-3xl -ml-16 -mt-16" />
                                    
                                    <div className="not-skew-x relative z-10">
                                        <div className="not-skew-x flex justify-between items-start mb-10">
                                            <div>
                                                <DialogTitle className="font-black italic text-4xl uppercase tracking-tighter text-foreground leading-none">
                                                    Add <span className="text-primary italic">New Book</span>
                                                </DialogTitle>
                                                <div className="h-1 w-20 bg-primary/40 mt-4 skew-x-[-24deg]" />
                                                <p className="text-[10px] font-mono font-black text-primary/60 uppercase tracking-[0.4em] mt-6 italic">Add a new book to the library collection</p>
                                            </div>
                                            <Button variant="ghost" size="icon" onClick={() => setIsAddBookOpen(false)} className="text-primary/40 hover:text-primary hover:bg-primary/10 -mt-4 -mr-4 rounded-none">
                                                <Plus className="h-6 w-6 rotate-45" />
                                            </Button>
                                        </div>

                                        <div className="space-y-8">
                                            <div className="grid grid-cols-2 gap-8">
                                                <div className="space-y-3">
                                                    <Label className="text-[9px] font-mono font-black uppercase text-foreground/40 tracking-[0.3em] italic">BOOK TITLE</Label>
                                                    <Input value={bookForm.title} onChange={(e) => setBookForm({ ...bookForm, title: e.target.value })} placeholder="TITLE_ID" className="h-14 rounded-none bg-background/50 border-primary/10 hover:border-primary/40 font-mono font-black uppercase text-xs transition-all placeholder:text-foreground/10" />
                                                </div>
                                                <div className="space-y-3">
                                                    <Label className="text-[9px] font-mono font-black uppercase text-foreground/40 tracking-[0.3em] italic">AUTHOR</Label>
                                                    <Input value={bookForm.author} onChange={(e) => setBookForm({ ...bookForm, author: e.target.value })} placeholder="AUTHOR_NAME" className="h-14 rounded-none bg-background/50 border-primary/10 hover:border-primary/40 font-mono font-black uppercase text-xs transition-all placeholder:text-foreground/10" />
                                                </div>
                                            </div>

                                            <div className="grid grid-cols-3 gap-8">
                                                <div className="space-y-3">
                                                    <Label className="text-[9px] font-mono font-black uppercase text-foreground/40 tracking-[0.3em] italic">ISBN</Label>
                                                    <Input value={bookForm.isbn} onChange={(e) => setBookForm({ ...bookForm, isbn: e.target.value })} placeholder="KEY_VALUE" className="h-14 rounded-none bg-background/50 border-primary/10 hover:border-primary/40 font-mono font-black text-xs transition-all placeholder:text-foreground/10" />
                                                </div>
                                                <div className="space-y-3">
                                                    <Label className="text-[9px] font-mono font-black uppercase text-foreground/40 tracking-[0.3em] italic">CATEGORY</Label>
