                                </table>
                            </div>
                        </div>
                    </div>
                </TabsContent>
            </Tabs>
        </div>
    );
}

"use client";

import { useState } from "react";
import {
    MessageSquare, Send, Search, Plus, Inbox, SendHorizonal, Mail, MailOpen, Clock, User,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ScrollArea } from "@/components/ui/scroll-area";
import { sendMessage, markMessageRead } from "@/app/actions/modules";
import { useRouter } from "next/navigation";
import { cn } from "@/lib/utils";

interface MessagesDashboardProps {
    inbox: any[];
    sent: any[];
    contacts: any[];
    currentUserId: string;
}

export function MessagesDashboard({ inbox, sent, contacts, currentUserId }: MessagesDashboardProps) {
    const router = useRouter();
    const [isComposeOpen, setIsComposeOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [selectedMessage, setSelectedMessage] = useState<any>(null);
    const [composeForm, setComposeForm] = useState({ receiver_id: "", subject: "", body: "" });

    const handleSend = async () => {
        if (!composeForm.receiver_id || !composeForm.body) return;
        setLoading(true);
        await sendMessage(composeForm);
        setLoading(false);
        setIsComposeOpen(false);
        setComposeForm({ receiver_id: "", subject: "", body: "" });
        router.refresh();
    };

    const handleOpenMessage = async (msg: any) => {
        setSelectedMessage(msg);
        if (!msg.is_read && msg.receiver_id === currentUserId) {
            await markMessageRead(msg.id);
            router.refresh();
        }
    };

    const unreadCount = inbox.filter(m => !m.is_read).length;

    const renderMessageList = (messages: any[], type: "inbox" | "sent") => (
        <div className="divide-y divide-slate-100">
            {messages.length === 0 ? (
                <div className="p-12 text-center text-muted-foreground font-medium">No messages yet.</div>
            ) : (
                messages.map((msg) => {
                    const person = type === "inbox" ? msg.sender : msg.receiver;
                    return (
                        <button
                            key={msg.id}
                            onClick={() => handleOpenMessage(msg)}
                            className={cn(
                                "w-full flex items-start gap-x-4 p-5 text-left transition-all hover:bg-white/60",
                                selectedMessage?.id === msg.id && "bg-white shadow-sm",
                                type === "inbox" && !msg.is_read && "bg-blue-50/50 border-l-4 border-blue-500"
                            )}
                        >
                            <div className={cn("h-10 w-10 rounded-xl flex items-center justify-center font-bold text-white shrink-0", type === "inbox" && !msg.is_read ? "bg-blue-500 neon-blue" : "bg-card")}>
                                {person?.full_name?.[0] || "?"}
                            </div>
                            <div className="flex-1 min-w-0">
                                <div className="flex justify-between items-baseline mb-1">
                                    <span className={cn("text-sm truncate", type === "inbox" && !msg.is_read ? "font-black text-foreground" : "font-bold text-slate-700")}>
                                        {person?.full_name}
                                    </span>
                                    <span className="text-[10px] font-bold text-muted-foreground shrink-0 ml-2">
                                        {new Date(msg.created_at).toLocaleDateString()}
                                    </span>
                                </div>
                                <p className="text-xs font-bold text-foreground/70 truncate">{msg.subject || "(No subject)"}</p>
                                <p className="text-[10px] text-muted-foreground truncate mt-0.5">{msg.body}</p>
                            </div>
                        </button>
                    );
                })
            )}
        </div>
    );

    return (
        <div className="h-[calc(100vh-160px)] flex gap-x-6 animate-in fade-in duration-700">
            {/* Message List Panel */}
            <Card className="w-96 border-none glass futuristic-card flex flex-col overflow-hidden">
                <CardHeader className="bg-card text-white p-5 shrink-0">
                    <div className="flex items-center justify-between">
                        <CardTitle className="text-sm font-black uppercase tracking-widest flex items-center gap-x-2">
                            <MessageSquare className="h-4 w-4 text-blue-400" /> Messages
                        </CardTitle>
                        <Dialog open={isComposeOpen} onOpenChange={setIsComposeOpen}>
                            <DialogTrigger asChild>
                                <Button size="sm" className="rounded-xl bg-blue-500 text-white font-bold gap-x-1 h-8 text-xs border-none">
                                    <Plus className="h-3 w-3" /> Compose
                                </Button>
                            </DialogTrigger>
                            <DialogContent className="glass border-none">
                                <DialogHeader><DialogTitle className="font-black text-2xl">New Message</DialogTitle></DialogHeader>
                                <div className="space-y-4 pt-4">
                                    <div className="space-y-2">
                                        <Label className="text-xs font-bold uppercase text-muted-foreground">To</Label>
                                        <Select value={composeForm.receiver_id} onValueChange={(v) => setComposeForm({ ...composeForm, receiver_id: v })}>
                                            <SelectTrigger><SelectValue placeholder="Select recipient" /></SelectTrigger>
                                            <SelectContent>
                                                {contacts.map(c => (
                                                    <SelectItem key={c.id} value={c.id}>
                                                        {c.full_name} ({c.role})
                                                    </SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                    <div className="space-y-2">
                                        <Label className="text-xs font-bold uppercase text-muted-foreground">Subject</Label>
                                        <Input value={composeForm.subject} onChange={(e) => setComposeForm({ ...composeForm, subject: e.target.value })} placeholder="Message subject" />
                                    </div>
                                    <div className="space-y-2">
                                        <Label className="text-xs font-bold uppercase text-muted-foreground">Message</Label>
                                        <textarea
                                            value={composeForm.body}
                                            onChange={(e) => setComposeForm({ ...composeForm, body: e.target.value })}
                                            placeholder="Type your message..."
                                            className="w-full h-32 rounded-xl border border-border p-4 text-sm resize-none focus:outline-none focus:ring-2 focus:ring-slate-900"
                                        />
                                    </div>
                                    <Button onClick={handleSend} disabled={loading} className="w-full rounded-xl py-6 bg-card text-white font-bold gap-x-2">
                                        <Send className="h-4 w-4" />
                                        {loading ? "Sending..." : "Send Message"}
                                    </Button>
                                </div>
                            </DialogContent>
                        </Dialog>
                    </div>
                    {unreadCount > 0 && (
                        <Badge className="mt-2 bg-blue-500/20 text-blue-300 border-none text-[10px] font-bold w-fit">{unreadCount} Unread</Badge>
                    )}
                </CardHeader>
                <Tabs defaultValue="inbox" className="flex-1 flex flex-col overflow-hidden">
                    <TabsList className="bg-transparent h-auto p-2 gap-x-1 shrink-0">
                        <TabsTrigger value="inbox" className="rounded-xl px-4 py-2 text-xs font-bold data-[state=active]:bg-white data-[state=active]:shadow-sm gap-x-1">
                            <Inbox className="h-3 w-3" /> Inbox ({inbox.length})
                        </TabsTrigger>
                        <TabsTrigger value="sent" className="rounded-xl px-4 py-2 text-xs font-bold data-[state=active]:bg-white data-[state=active]:shadow-sm gap-x-1">
                            <SendHorizonal className="h-3 w-3" /> Sent ({sent.length})
                        </TabsTrigger>
                    </TabsList>
                    <ScrollArea className="flex-1">
                        <TabsContent value="inbox" className="m-0">{renderMessageList(inbox, "inbox")}</TabsContent>
                        <TabsContent value="sent" className="m-0">{renderMessageList(sent, "sent")}</TabsContent>
                    </ScrollArea>
                </Tabs>
            </Card>

            {/* Message Detail Panel */}
            <Card className="flex-1 border-none glass futuristic-card flex flex-col overflow-hidden relative">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-purple-500 opacity-20" />
                {selectedMessage ? (
                    <>
                        <div className="p-6 border-b border-border bg-white/40 backdrop-blur-sm shrink-0">
                            <div className="flex items-center gap-x-4">
                                <div className="h-12 w-12 rounded-2xl bg-card text-white flex items-center justify-center shadow-xl neon-blue font-black text-xl">
                                    {(selectedMessage.sender?.full_name || selectedMessage.receiver?.full_name)?.[0] || "?"}
                                </div>
                                <div className="flex-1">
                                    <h3 className="font-black text-foreground tracking-tight">
                                        {selectedMessage.sender?.full_name || selectedMessage.receiver?.full_name}
                                    </h3>
                                    <p className="text-xs font-bold text-muted-foreground">{selectedMessage.subject || "(No subject)"}</p>
                                </div>
                                <div className="text-right">
                                    <Badge variant="outline" className="font-bold text-[10px]">
                                        {selectedMessage.sender?.role || selectedMessage.receiver?.role || "User"}
                                    </Badge>
                                    <p className="text-[10px] text-muted-foreground mt-1 font-mono">
                                        {new Date(selectedMessage.created_at).toLocaleString()}
                                    </p>
                                </div>
                            </div>
                        </div>
                        <ScrollArea className="flex-1 p-8">
                            <div className="prose prose-sm max-w-none">
                                <p className="text-slate-700 font-medium leading-relaxed whitespace-pre-wrap">{selectedMessage.body}</p>
                            </div>
                        </ScrollArea>
                    </>
                ) : (
                    <div className="flex-1 flex items-center justify-center">
                        <div className="text-center">
                            <Mail className="h-16 w-16 mx-auto text-slate-200 mb-4" />
                            <h3 className="font-black text-lg text-slate-300">Select a message</h3>
                            <p className="text-xs text-muted-foreground font-medium mt-1">Choose a message from the list to read</p>
                        </div>
                    </div>
                )}
            </Card>
        </div>
    );
}

"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { createClient } from "@/lib/supabase/client";

import { useTransition } from "react";
import { createParent } from "@/app/actions/parents";

const parentSchema = z.object({
  first_name: z.string().min(2, "First name is too short"),
  last_name: z.string().min(2, "Last name is too short"),
  email: z.string().email("Invalid email"),
  phone: z.string().min(10, "Phone number is required"),
  occupation: z.string().optional(),
  relation_to_student: z
    .string()
    .min(2, "Relation is required (e.g. Father, Mother)"),
});

type ParentFormValues = z.infer<typeof parentSchema>;

interface ParentFormProps {
  studentId: string;
  onSuccess: () => void;
}

export function ParentForm({ studentId, onSuccess }: ParentFormProps) {
  const [isPending, startTransition] = useTransition();
  const form = useForm<ParentFormValues>({
    resolver: zodResolver(parentSchema),
    defaultValues: {
      first_name: "",
      last_name: "",
      email: "",
      phone: "",
      occupation: "",
      relation_to_student: "",
    },
  });

  async function onSubmit(values: ParentFormValues) {
    startTransition(async () => {
      try {
        const res = await createParent({ ...values, studentId });
        if (res.error) {
          toast.error(res.error);
          return;
        }
        toast.success("Parent profile created and linked successfully");
        onSuccess();
      } catch (error) {
        toast.error("Something went wrong");
      }
    });
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 p-8">
        <div className="grid grid-cols-2 gap-4">
          <FormField
            control={form.control}
            name="first_name"
            render={({ field }) => (
              <FormItem className="space-y-1">
                <FormLabel className="text-[10px] font-black uppercase text-primary tracking-widest">First Name</FormLabel>
                <FormControl>
                  <Input placeholder="Michael" {...field} className="rounded-sm bg-background/50 border-border font-bold text-xs uppercase tracking-tight" />
                </FormControl>
                <FormMessage className="text-[9px] font-bold uppercase" />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="last_name"
            render={({ field }) => (
              <FormItem className="space-y-1">
                <FormLabel className="text-[10px] font-black uppercase text-primary tracking-widest">Last Name</FormLabel>
                <FormControl>
                  <Input placeholder="Doe" {...field} className="rounded-sm bg-background/50 border-border font-bold text-xs uppercase tracking-tight" />
                </FormControl>
                <FormMessage className="text-[9px] font-bold uppercase" />
              </FormItem>
            )}
          />
        </div>
        <FormField
          control={form.control}
          name="email"
          render={({ field }) => (
            <FormItem className="space-y-1">
              <FormLabel className="text-[10px] font-black uppercase text-primary tracking-widest">Email Address</FormLabel>
              <FormControl>
                <Input placeholder="michael.doe@example.com" {...field} className="rounded-sm bg-background/50 border-border font-bold text-xs uppercase tracking-tight" />
              </FormControl>
              <FormMessage className="text-[9px] font-bold uppercase" />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="phone"
          render={({ field }) => (
            <FormItem className="space-y-1">
              <FormLabel className="text-[10px] font-black uppercase text-primary tracking-widest">Phone Number</FormLabel>
              <FormControl>
                <Input placeholder="+1 234 567 890" {...field} className="rounded-sm bg-background/50 border-border font-mono font-bold text-xs uppercase tracking-tight" />
              </FormControl>
              <FormMessage className="text-[9px] font-bold uppercase" />
            </FormItem>
          )}
        />
        <div className="grid grid-cols-2 gap-4">
          <FormField
            control={form.control}
            name="occupation"
            render={({ field }) => (
              <FormItem className="space-y-1">
                <FormLabel className="text-[10px] font-black uppercase text-primary tracking-widest">Occupation</FormLabel>
                <FormControl>
                  <Input placeholder="Sector Specialist" {...field} className="rounded-sm bg-background/50 border-border font-bold text-xs uppercase tracking-tight" />
                </FormControl>
                <FormMessage className="text-[9px] font-bold uppercase" />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="relation_to_student"
            render={({ field }) => (
              <FormItem className="space-y-1">
                <FormLabel className="text-[10px] font-black uppercase text-primary tracking-widest">Relation to Student</FormLabel>
                <FormControl>
                  <Input placeholder="Father, Mother, etc." {...field} className="rounded-sm bg-background/50 border-border font-bold text-xs uppercase tracking-tight" />
                </FormControl>
                <FormMessage className="text-[9px] font-bold uppercase" />
              </FormItem>
            )}
          />
        </div>
        <div className="flex justify-end gap-x-3 pt-6">
          <Button variant="ghost" type="button" onClick={() => onSuccess()} className="text-[10px] font-black uppercase tracking-widest text-foreground/40 hover:text-foreground hover:bg-foreground/5 rounded-sm px-6">
            Cancel
          </Button>
          <Button type="submit" disabled={isPending} className="bg-primary text-primary-foreground font-black uppercase tracking-[0.2em] emerald-glow rounded-sm px-8 shadow-xl text-[10px]">
            {isPending ? "Saving..." : "Add Parent"}
          </Button>
        </div>
      </form>
    </Form>
  );
}

"use client";

import { useState } from "react";
import {
    Settings,
    CreditCard,
    Building2,
    Bell,
    ActivitySquare,
    Globe,
    Lock,
    RefreshCw,
    Save,
    GraduationCap,
    Banknote,
    Mail,
    ShieldCheck,
    CheckCircle2,
    XCircle
} from "lucide-react";
import {
    Card,
    CardHeader,
    CardTitle,
    CardContent,
    CardDescription
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { updateSettings } from "@/app/actions/settings";
import { updateGatewayStatus } from "@/app/actions/gateways";
import { toast } from "sonner";

export default function SettingsDashboardClient({
    initialSettings,
    initialGateways,
    academicYears,
}: {
    initialSettings: any;
    initialGateways: any[];
    academicYears: any[];
}) {
    const [activeTab, setActiveTab] = useState("identity");
    const [settings, setSettings] = useState(initialSettings);
    const [gateways, setGateways] = useState(initialGateways || []);
    const [isSaving, setIsSaving] = useState(false);

    const handleSaveSettings = async (category: string, keys: string[]) => {
        setIsSaving(true);
        const settingsToSave: Record<string, string> = {};
        keys.forEach(key => {
            settingsToSave[key] = settings[key] || "";
        });

        const result = await updateSettings(settingsToSave, category);
        setIsSaving(false);

        if (result.success) {
            toast.success(`${category.charAt(0).toUpperCase() + category.slice(1)} settings updated`);
        } else {
            toast.error(result.error);
        }
    };

    const handleToggleGateway = async (id: string, currentStatus: boolean) => {
        const result = await updateGatewayStatus(id, !currentStatus);
        if (result.success) {
            setGateways(gateways.map(g => g.id === id ? { ...g, is_active: !currentStatus } : g));
            toast.success("Gateway status updated");
        } else {
            toast.error(result.error);
        }
    };

    const tabs = [
        { id: "identity", label: "Identity", icon: Building2 },
        { id: "academic", label: "Academic", icon: GraduationCap },
        { id: "financial", label: "Financial", icon: Banknote },
        { id: "gateways", label: "Payment Gateways", icon: CreditCard },
        { id: "communication", label: "Communication", icon: Mail },
        { id: "security", label: "Security & Policy", icon: ShieldCheck },
    ];

    return (
        <div className="space-y-8 animate-in fade-in duration-700 pb-12 w-full max-w-6xl mx-auto">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-4xl font-black tracking-tighter text-foreground uppercase italic underline decoration-primary/30 underline-offset-8">
                        Infrastructure Config
                    </h2>
                    <p className="text-primary font-black uppercase text-[10px] tracking-[0.3em] mt-3 bg-primary/10 w-fit px-3 py-1 rounded-sm border border-primary/20">
                        Institutional Core Architecture & System Protocol
                    </p>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                {/* Navigation Sidebar */}
                <div className="md:col-span-1 space-y-2">
                    {tabs.map((item) => (
                        <button
                            key={item.id}
                            onClick={() => setActiveTab(item.id)}
                            className={`w-full flex items-center gap-x-3 px-5 py-4 rounded-sm text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === item.id
                                ? "bg-primary text-primary-foreground shadow-2xl emerald-glow italic scale-[1.02]"
                                : "text-foreground/40 hover:bg-primary/10 hover:text-primary border border-transparent hover:border-primary/20"
                                }`}
                        >
                            <item.icon className="h-4 w-4" />
                            {item.label}
                        </button>
                    ))}
                </div>

                {/* Content Area */}
                <div className="md:col-span-3 space-y-6">
                    {activeTab === "identity" && (
                        <Card className="border-border bg-card/40 backdrop-blur-xl rounded-sm overflow-hidden shadow-2xl">
                            <CardHeader className="bg-primary/10 border-b border-primary/20 flex flex-row items-center justify-between space-y-0 p-6">
                                <CardTitle className="text-[11px] font-black uppercase tracking-[0.2em] text-primary flex items-center gap-x-3 italic">
                                    <Globe className="h-4 w-4" />
                                    Institutional Alias & Signature
                                </CardTitle>
                                <Button
                                    size="sm"
                                    onClick={() => handleSaveSettings('identity', ['school_name', 'contact_email', 'contact_phone', 'school_address', 'logo_url'])}
                                    disabled={isSaving}
                                    className="rounded-sm bg-primary text-primary-foreground text-[10px] font-black uppercase tracking-widest gap-x-2 emerald-glow px-6 py-5 h-auto shadow-xl"
                                >
                                    {isSaving ? <RefreshCw className="h-3 w-3 animate-spin" /> : <Save className="h-3 w-3" />}
                                    Commit Changes
                                </Button>
                            </CardHeader>
                            <CardContent className="p-10 space-y-8">
                                <div className="grid grid-cols-2 gap-8">
                                    <div className="space-y-2 col-span-2">
                                        <Label className="text-[10px] font-black uppercase text-primary tracking-widest">Entity Designation</Label>
                                        <Input
                                            value={settings.school_name || ""}
                                            onChange={(e) => setSettings({ ...settings, school_name: e.target.value })}
                                            className="bg-background/50 border-border h-12 rounded-sm font-bold uppercase tracking-tight"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-black uppercase text-primary tracking-widest">Primary Liaison (Email)</Label>
                                        <Input
                                            value={settings.contact_email || ""}
                                            onChange={(e) => setSettings({ ...settings, contact_email: e.target.value })}
                                            className="bg-background/50 border-border h-12 rounded-sm font-bold uppercase tracking-tight"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-black uppercase text-primary tracking-widest">Telemetric Link (Phone)</Label>
                                        <Input
                                            value={settings.contact_phone || ""}
                                            onChange={(e) => setSettings({ ...settings, contact_phone: e.target.value })}
                                            className="bg-background/50 border-border h-12 rounded-sm font-bold uppercase tracking-tight"
                                        />
                                    </div>
                                    <div className="space-y-2 col-span-2">
                                        <Label className="text-[10px] font-black uppercase text-primary tracking-widest">Geographical Coordinates (Address)</Label>
                                        <Input
                                            value={settings.school_address || ""}
                                            onChange={(e) => setSettings({ ...settings, school_address: e.target.value })}
                                            className="bg-background/50 border-border h-12 rounded-sm font-bold uppercase tracking-tight"
                                        />
                                    </div>
                                    <div className="space-y-2 col-span-2">
                                        <Label className="text-[10px] font-black uppercase text-primary tracking-widest">Visual Asset Identifier (Logo URL)</Label>
                                        <Input
                                            value={settings.logo_url || ""}
                                            onChange={(e) => setSettings({ ...settings, logo_url: e.target.value })}
                                            className="bg-background/50 border-border h-12 rounded-sm font-bold placeholder:text-foreground/10"
                                            placeholder="https://institutional-assets.io/signature.png"
                                        />
                                    </div>
                                </div>
                            </CardContent>
                        </Card>
                    )}

                    {activeTab === "academic" && (
                        <Card className="border-border bg-card/40 backdrop-blur-xl rounded-sm overflow-hidden shadow-2xl">
                            <CardHeader className="bg-primary/10 border-b border-primary/20 flex flex-row items-center justify-between space-y-0 p-6">
                                <CardTitle className="text-[11px] font-black uppercase tracking-[0.2em] text-primary flex items-center gap-x-3 italic">
                                    <GraduationCap className="h-4 w-4" />
                                    Temporal Protocol Configuration
                                </CardTitle>
                                <Button
                                    size="sm"
                                    onClick={() => handleSaveSettings('academic', ['current_academic_year_id', 'result_visibility'])}
                                    disabled={isSaving}
                                    className="rounded-sm bg-primary text-primary-foreground text-[10px] font-black uppercase tracking-widest gap-x-2 emerald-glow px-6 py-5 h-auto shadow-xl"
                                >
                                    {isSaving ? <RefreshCw className="h-3 w-3 animate-spin" /> : <Save className="h-3 w-3" />}
                                    Sync Cycle
                                </Button>
                            </CardHeader>
                            <CardContent className="p-8 space-y-6">
                                <div className="space-y-6">
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-black uppercase text-primary tracking-widest">Current Academic Year</Label>
                                        <Select
                                            value={settings.current_academic_year_id || ""}
                                            onValueChange={(val) => setSettings({ ...settings, current_academic_year_id: val })}
                                        >
                                            <SelectTrigger className="h-12 rounded-sm bg-background/50 border-border font-bold uppercase tracking-tight">
                                                <SelectValue placeholder="Select active session" />
                                            </SelectTrigger>
                                            <SelectContent className="bg-background border-border rounded-sm">
                                                {academicYears.map(year => (
                                                    <SelectItem key={year.id} value={year.id} className="font-bold uppercase text-[10px] hover:bg-primary/10 hover:text-primary transition-all">{year.name}</SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                        <p className="text-[9px] text-foreground/40 font-black uppercase tracking-widest mt-2 italic">Master temporal reference for all Registry Nodes and grading sequences.</p>
                                    </div>
                                    <div className="flex items-center justify-between p-6 bg-primary/5 rounded-sm border border-primary/20 backdrop-blur-md shadow-inner">
                                        <div className="space-y-1">
                                            <Label className="text-[11px] font-black text-foreground uppercase tracking-widest">Publish Diagnostic Results</Label>
                                            <p className="text-[9px] text-foreground/40 font-black uppercase tracking-widest italic">Broadcast academic telemetry to Guardian and Student nodes.</p>
                                        </div>
                                        <Switch
                                            checked={settings.result_visibility === "true"}
                                            onCheckedChange={(checked) => setSettings({ ...settings, result_visibility: checked ? "true" : "false" })}
                                            className="data-[state=checked]:bg-primary"
                                        />
                                    </div>
                                </div>
                            </CardContent>
                        </Card>
                    )}

                    {activeTab === "financial" && (
                        <Card className="border-border bg-card/40 backdrop-blur-xl rounded-sm overflow-hidden shadow-2xl">
                            <CardHeader className="bg-primary/10 border-b border-primary/20 flex flex-row items-center justify-between space-y-0 p-6">
                                <CardTitle className="text-[11px] font-black uppercase tracking-[0.2em] text-primary flex items-center gap-x-3 italic">
                                    <Banknote className="h-4 w-4" />
                                    Economic & Fee Protocols
                                </CardTitle>
                                <Button
                                    size="sm"
                                    onClick={() => handleSaveSettings('finance', ['currency', 'currency_symbol', 'late_fee_per_day', 'tax_label', 'tax_rate'])}
                                    disabled={isSaving}
                                    className="rounded-sm bg-primary text-primary-foreground text-[10px] font-black uppercase tracking-widest gap-x-2 emerald-glow px-6 py-5 h-auto shadow-xl"
                                >
                                    {isSaving ? <RefreshCw className="h-3 w-3 animate-spin" /> : <Save className="h-3 w-3" />}
                                    Update Ledger
                                </Button>
                            </CardHeader>
                            <CardContent className="p-10 space-y-8">
                                <div className="grid grid-cols-2 gap-8">
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-black uppercase text-primary tracking-widest">Global Currency Protocol</Label>
                                        <Input
                                            value={settings.currency || ""}
                                            onChange={(e) => setSettings({ ...settings, currency: e.target.value })}
                                            className="bg-background/50 border-border h-12 rounded-sm font-bold uppercase tracking-tight"
                                            placeholder="USD"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <Label className="text-[10px] font-black uppercase text-primary tracking-widest">Symbolic Denominator</Label>
                                        <Input
                                            value={settings.currency_symbol || ""}
                                            onChange={(e) => setSettings({ ...settings, currency_symbol: e.target.value })}
                                            className="bg-background/50 border-border h-12 rounded-sm font-bold uppercase tracking-tight"
                                            placeholder="$"
                                        />
                                    </div>
