                            <DropdownMenuItem
                              onClick={() => onLinkParent(student.id)}
                              className="gap-x-2 cursor-pointer font-bold uppercase text-[10px] tracking-tight focus:bg-primary/10 focus:text-primary px-3 py-2"
                            >
                              <UserPlus className="h-3.5 w-3.5" /> Link Guardian
                            </DropdownMenuItem>
                            <DropdownMenuSeparator className="bg-border/50" />
                            <DropdownMenuItem
                              onClick={() => {
                                if (confirm("Delete this student record?")) {
                                  startTransition(async () => {
                                    const res = await deleteStudent(student.id);
                                    if (res.error) toast.error(res.error);
                                    else toast.success("Student deleted successfully");
                                  });
                                }
                              }}
                              className="gap-x-2 text-red-500 focus:text-red-600 cursor-pointer font-bold uppercase text-[10px] tracking-tight focus:bg-red-500/10 px-3 py-2"
                            >
                              <Trash2 className="h-3.5 w-3.5" /> Delete Record
                            </DropdownMenuItem>
                          </>
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>

      <Dialog open={isOpen} onOpenChange={setIsOpen}>
        <DialogContent className="p-0 border-none bg-background/95 backdrop-blur-2xl max-w-xl overflow-hidden ring-1 ring-primary/20">
          <div className="bg-primary p-8 text-primary-foreground">
            <DialogHeader>
              <DialogTitle className="font-black text-2xl uppercase tracking-tighter">
                {editingStudent ? "Modify Student Profile" : "Initialize Student Node"}
              </DialogTitle>
              <p className="text-primary-foreground/70 text-xs font-bold uppercase tracking-widest mt-1">
                Institutional Registry Configuration
              </p>
            </DialogHeader>
          </div>
          <StudentForm
            initialData={editingStudent}
            onSuccess={() => setIsOpen(false)}
          />
        </DialogContent>
      </Dialog>

      <Dialog open={isParentOpen} onOpenChange={setIsParentOpen}>
        <DialogContent className="p-0 border-none bg-background/95 backdrop-blur-2xl max-w-lg overflow-hidden ring-1 ring-primary/20">
          <div className="bg-primary p-8 text-primary-foreground">
            <DialogHeader>
              <DialogTitle className="font-black text-2xl uppercase tracking-tighter text-center">Initialize Guardian Node</DialogTitle>
              <p className="text-primary-foreground/70 text-xs font-bold uppercase tracking-widest text-center mt-1">Registry Liaison Management</p>
            </DialogHeader>
          </div>
          <div className="p-2">
            {linkingStudentId && (
              <ParentForm
                studentId={linkingStudentId}
                onSuccess={() => setIsParentOpen(false)}
              />
            )}
          </div>
        </DialogContent>
      </Dialog>

      <Dialog open={isBulkImportOpen} onOpenChange={setIsBulkImportOpen}>
        <DialogContent className="sm:max-w-[600px] glass border-white/20">
          <BulkImportModal
            onSuccess={() => setIsBulkImportOpen(false)}
            onCancel={() => setIsBulkImportOpen(false)}
          />
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useForm } from "react-hook-form";
import { BookOpen, Pencil, Plus, Trash2 } from "lucide-react";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Subject } from "@/types/database";
import { toast } from "sonner";
import { createSubject, updateSubject } from "@/app/actions/subjects";
import { useRouter } from "next/navigation";

const subjectSchema = z.object({
  name: z.string().min(2, "Subject name is too short"),
  code: z.string().min(2, "Subject code is required"),
  credits: z.coerce.number().min(1).max(10),
  description: z.string().optional(),
  syllabus: z.string().optional(),
});

type SubjectFormValues = z.infer<typeof subjectSchema>;

interface SubjectFormProps {
  initialData?: Subject | null;
  onSuccess: () => void;
}

export function SubjectForm({ initialData, onSuccess }: SubjectFormProps) {
  const router = useRouter();
  const form = useForm<SubjectFormValues>({
    resolver: zodResolver(subjectSchema),
    defaultValues: {
      name: initialData?.name || "",
      code: initialData?.code || "",
      credits: initialData?.credits || 4,
      description: initialData?.description || "",
      syllabus: initialData?.syllabus || "",
    },
  });

  async function onSubmit(values: SubjectFormValues) {
    try {
      let result;
      if (initialData) {
        result = await updateSubject(initialData.id, values);
      } else {
        result = await createSubject(values);
      }

      if (result.success) {
        toast.success(initialData ? "Node Modified" : "Node Initialized");
        router.refresh();
        onSuccess();
      } else {
        toast.error(result.error || "Execution Failure");
      }
    } catch (error) {
      toast.error("Critical System Error");
    }
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-8 p-10 bg-card relative">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-10">
          <div className="col-span-1">
            <FormField<SubjectFormValues>
              control={form.control}
              name="name"
              render={({ field }) => (
                <FormItem className="space-y-1.5">
                  <FormLabel className="text-[10px] font-bold uppercase text-muted-foreground tracking-wider ml-1">Subject Name</FormLabel>
                  <FormControl>
                    <Input 
                      placeholder="e.g. Mathematics" 
                      {...field} 
                      className="h-11 rounded-md border-border bg-muted/20 font-semibold focus:border-primary transition-all px-4" 
                    />
                  </FormControl>
                  <FormMessage className="text-[10px] font-bold text-destructive" />
                </FormItem>
              )}
            />
          </div>
          <div className="col-span-1">
            <FormField<SubjectFormValues>
              control={form.control}
              name="code"
              render={({ field }) => (
                <FormItem className="space-y-1.5">
                  <FormLabel className="text-[10px] font-bold uppercase text-muted-foreground tracking-wider ml-1">Subject Code</FormLabel>
                  <FormControl>
                    <Input 
                      placeholder="e.g. MATH-101" 
                      {...field} 
                      className="h-11 rounded-md border-border bg-muted/20 font-mono font-bold focus:border-primary transition-all px-4" 
                    />
                  </FormControl>
                  <FormMessage className="text-[10px] font-bold text-destructive" />
                </FormItem>
              )}
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-10">
          <div className="col-span-1">
            <FormField<SubjectFormValues>
              control={form.control}
              name="credits"
              render={({ field }) => (
                <FormItem className="space-y-1.5">
                  <FormLabel className="text-[10px] font-bold uppercase text-muted-foreground tracking-wider ml-1">Credits</FormLabel>
                  <FormControl>
                    <div className="relative">
                      <Input 
                        type="number" 
                        min={1} 
                        max={10} 
                        {...field} 
                        className="h-11 rounded-md border-border bg-muted/20 font-bold text-lg focus:border-primary transition-all px-4" 
                      />
                      <div className="absolute right-4 top-1/2 -translate-y-1/2 font-bold text-[10px] text-muted-foreground uppercase tracking-widest pointer-events-none">Points</div>
                    </div>
                  </FormControl>
                  <FormMessage className="text-[10px] font-bold text-destructive" />
                </FormItem>
              )}
            />
          </div>
          <div className="col-span-1 flex items-end">
            <div className="h-11 w-full bg-muted/10 rounded-md border border-dashed border-border flex items-center justify-center">
               <span className="text-[9px] font-bold text-muted-foreground uppercase tracking-widest">Verification Pending</span>
            </div>
          </div>
        </div>
        

        <FormField<SubjectFormValues>
          control={form.control}
          name="description"
          render={({ field }) => (
            <FormItem className="space-y-1.5 relative z-10">
              <FormLabel className="text-[10px] font-bold uppercase text-muted-foreground tracking-wider ml-1">Description</FormLabel>
              <FormControl>
                <Textarea
                  placeholder="Enter subject description..."
                  className="resize-none rounded-md border-border bg-muted/20 min-h-[100px] font-medium text-sm py-4 px-4 focus:border-primary transition-all shadow-sm"
                  {...field}
                />
              </FormControl>
              <FormMessage className="text-[10px] font-bold text-destructive" />
            </FormItem>
          )}
        />

        <FormField<SubjectFormValues>
          control={form.control}
          name="syllabus"
          render={({ field }) => (
            <FormItem className="space-y-1.5 relative z-10">
              <FormLabel className="text-[10px] font-bold uppercase text-muted-foreground tracking-wider ml-1">Syllabus Overview</FormLabel>
              <FormControl>
                <Textarea
                  placeholder="Enter syllabus details or curriculum breakdown..."
                  className="resize-none rounded-md border-border bg-muted/20 min-h-[160px] font-medium text-sm py-4 px-4 focus:border-primary transition-all shadow-sm"
                  {...field}
                />
              </FormControl>
              <FormMessage className="text-[10px] font-bold text-destructive" />
            </FormItem>
          )}
        />

        <div className="flex flex-col md:flex-row items-center gap-4 pt-8 relative z-10">
          <Button 
            variant="ghost" 
            type="button" 
            onClick={() => onSuccess()} 
            className="w-full md:w-1/3 h-11 text-[11px] font-bold uppercase tracking-wider text-muted-foreground hover:text-destructive hover:bg-destructive/5 rounded-md transition-all border border-transparent hover:border-destructive/20"
          >
            Cancel
          </Button>
          <Button 
            type="submit" 
            className="w-full md:flex-1 h-11 bg-primary text-primary-foreground font-bold uppercase tracking-widest rounded-md shadow-lg transition-all hover:bg-primary/90 text-[11px]"
          >
             {initialData ? "Update Subject" : "Create Subject"}
          </Button>
        </div>
      </form>
    </Form>
  );
}

"use client";

import { useState } from "react";
import { MoreHorizontal, Pencil, Trash2, Plus, BookOpen } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Subject } from "@/types/database";
import { toast } from "sonner";
import { SubjectForm } from "./SubjectForm";
import { deleteSubject } from "@/app/actions/subjects";
import { useRouter } from "next/navigation";

interface SubjectListProps {
  initialData: Subject[];
}

export function SubjectList({ initialData }: SubjectListProps) {
  const router = useRouter();
  const [data, setData] = useState<Subject[]>(initialData);
  const [isOpen, setIsOpen] = useState(false);
  const [editingSubject, setEditingSubject] = useState<Subject | null>(null);

  const onAdd = () => {
    setEditingSubject(null);
    setIsOpen(true);
  };

  const onEdit = (subject: Subject) => {
    setEditingSubject(subject);
    setIsOpen(true);
  };

  const onDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this subject?")) return;
    const res = await deleteSubject(id);
    if (res.success) {
      toast.success("Subject deleted successfully");
      router.refresh();
      setData(data.filter((s) => s.id !== id));
    } else {
      toast.error(res.error || "Failed to delete subject");
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in transition-all duration-700 relative">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 border-b border-border pb-8 relative z-10">
        <div className="flex items-center gap-x-6">
          <div className="h-14 w-14 bg-primary/10 rounded-lg flex items-center justify-center text-primary shadow-sm border border-primary/20">
            <BookOpen className="h-7 w-7" />
          </div>
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-foreground">Subject Registry</h1>
            <p className="text-[12px] font-semibold uppercase tracking-wider text-muted-foreground mt-1 flex items-center gap-2">
              <span className="h-1.5 w-1.5 rounded-full bg-primary" /> Core Academic Curriculum
            </p>
          </div>
        </div>
        
        <Button 
          onClick={onAdd} 
          className="h-11 px-8 bg-primary text-primary-foreground font-bold rounded-md hover:bg-primary/90 transition-all shadow-md flex items-center gap-3 uppercase tracking-wider text-[11px]"
        >
          <Plus className="h-4 w-4" /> Add New Subject
        </Button>
      </div>

       <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3 reveal-2 relative z-10">
        {data.length === 0 ? (
          <div className="col-span-full h-64 flex flex-col items-center justify-center bg-muted/5 border border-dashed border-border rounded-xl">
            <BookOpen className="h-12 w-12 text-muted-foreground/20 mb-4" />
            <p className="text-[12px] font-bold text-muted-foreground uppercase tracking-widest italic">No subject records found</p>
          </div>
        ) : (
          data.map((subject, i) => (
             <div
              key={subject.id}
              className="group relative transition-all duration-300 hover:shadow-md rounded-xl border border-border bg-card overflow-hidden"
            >
              <div className="relative">
                <div className="bg-muted/30 border-b border-border p-5 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="h-2 w-2 rounded-full bg-primary" />
                    <span className="font-bold text-[11px] text-muted-foreground tracking-wider uppercase">
                      {subject.code || `SUB-${subject.id.slice(0, 4).toUpperCase()}`}
                    </span>
                  </div>
                  
                   <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" className="h-8 w-8 p-0 text-muted-foreground hover:text-primary transition-all">
                        <MoreHorizontal className="h-4 w-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="p-1 border border-border shadow-xl rounded-lg">
                      <DropdownMenuLabel className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground px-3 py-2">Subject Actions</DropdownMenuLabel>
                      <DropdownMenuSeparator />
                       <DropdownMenuItem
                        onClick={() => onEdit(subject)}
                        className="gap-x-3 cursor-pointer font-bold uppercase text-[10px] tracking-wide py-2 px-3 rounded-md focus:bg-primary/10 focus:text-primary"
                      >
                        <Pencil className="h-3.5 w-3.5" /> Edit Subject
                      </DropdownMenuItem>
                      <DropdownMenuItem
                        onClick={() => onDelete(subject.id)}
                        className="gap-x-3 text-destructive focus:text-destructive cursor-pointer font-bold uppercase text-[10px] tracking-wide py-2 px-3 rounded-md focus:bg-destructive/10"
                      >
                        <Trash2 className="h-3.5 w-3.5" /> Delete Subject
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>

                <div className="p-8 space-y-6">
                  <div className="space-y-3">
                    <h4 className="font-bold text-foreground text-xl tracking-tight">
                      {subject.name}
                    </h4>
                    <p className="text-[12px] text-muted-foreground font-medium leading-relaxed line-clamp-2">
                      {subject.description || "Core academic subject focused on providing comprehensive foundational knowledge in the designated field."}
                    </p>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="p-4 bg-muted/20 border border-border rounded-lg">
                      <p className="text-[9px] font-bold text-muted-foreground uppercase tracking-widest mb-1.5">Credits</p>
                      <p className="text-2xl font-bold text-primary tabular-nums">{subject.credits || 0}<span className="text-[10px] lowercase text-muted-foreground/60 ml-1 font-semibold">pts</span></p>
                    </div>
                    <div className="p-4 bg-muted/20 border border-border rounded-lg">
                      <p className="text-[9px] font-bold text-muted-foreground uppercase tracking-widest mb-1.5">Status</p>
                      <div className="flex items-center gap-2 mt-1">
                        <span className="h-2 w-2 rounded-full bg-emerald-500" />
                        <span className="text-[11px] font-bold text-foreground uppercase tracking-wider">Active</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

       <Dialog open={isOpen} onOpenChange={setIsOpen}>
        <DialogContent className="max-w-2xl p-0 border-none rounded-xl overflow-hidden shadow-2xl">
          <div className="bg-primary/5 border-b border-border p-10 text-center">
            <DialogHeader>
              <DialogTitle className="text-3xl font-bold tracking-tight text-foreground">
                {editingSubject ? "Update Subject" : "Create New Subject"}
              </DialogTitle>
              <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-[0.3em] mt-3 flex items-center justify-center gap-3">
                <span className="h-px w-8 bg-border" /> Curriculum Definition <span className="h-px w-8 bg-border" />
              </p>
            </DialogHeader>
          </div>
          
           <div className="p-2">
            <SubjectForm
              initialData={editingSubject}
              onSuccess={() => setIsOpen(false)}
            />
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useDropzone } from "react-dropzone";
import Papa from "papaparse";
import { UploadCloud, FileType, CheckCircle2, AlertCircle, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { bulkImportTeachers, BulkTeacherRecord } from "@/app/actions/bulk-import";
import { z } from "zod";

interface BulkImportTeacherModalProps {
    onSuccess: () => void;
    onCancel: () => void;
}

const CsvRowSchema = z.object({
    first_name: z.string().min(1),
    last_name: z.string().min(1),
    email: z.string().email(),
    employee_id: z.string().min(1),
    specialization: z.string().optional(),
    qualification: z.string().min(1),
});

export function BulkImportTeacherModal({ onSuccess, onCancel }: BulkImportTeacherModalProps) {
    const [file, setFile] = useState<File | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [previewData, setPreviewData] = useState<BulkTeacherRecord[]>([]);
    const [errors, setErrors] = useState<string[]>([]);
    const [importResult, setImportResult] = useState<{
        successCount: number;
        failCount: number;
        errors: string[];
    } | null>(null);

    const onDrop = (acceptedFiles: File[]) => {
        if (acceptedFiles.length === 0) return;
        const selectedFile = acceptedFiles[0];
        setFile(selectedFile);
        setErrors([]);
        setImportResult(null);

        Papa.parse(selectedFile, {
            header: true,
            skipEmptyLines: true,
            complete: (results) => {
                const parsedRows: BulkTeacherRecord[] = [];
                const parsingErrors: string[] = [];

                results.data.forEach((row: any, index: number) => {
                    try {
                        const cleanRow = {
                            first_name: row.first_name?.trim(),
                            last_name: row.last_name?.trim(),
                            email: row.email?.trim(),
                            employee_id: row.employee_id?.trim(),
                            specialization: row.specialization?.trim() || undefined,
                            qualification: row.qualification?.trim(),
                        };

                        CsvRowSchema.parse(cleanRow);
                        parsedRows.push(cleanRow as BulkTeacherRecord);
                    } catch (e: any) {
                        parsingErrors.push(`Row ${index + 2}: Invalid data format.`);
                    }
                });

                if (parsingErrors.length > 0) {
                    setErrors(parsingErrors);
                } else {
                    setPreviewData(parsedRows);
                }
            },
            error: (error) => {
                setErrors([`Failed to parse CSV: ${error.message}`]);
            },
        });
    };

    const { getRootProps, getInputProps, isDragActive } = useDropzone({
        onDrop,
        accept: {
            "text/csv": [".csv"],
        },
        maxFiles: 1,
    });

    const handleImport = async () => {
        if (previewData.length === 0) return;

        setIsProcessing(true);
        setErrors([]);

        const result = await bulkImportTeachers(previewData);

        setIsProcessing(false);

        if (result.error) {
            toast.error(result.error);
        } else {
            setImportResult({
                successCount: result.successCount || 0,
                failCount: result.failCount || 0,
                errors: result.errors || [],
            });
            if (result.failCount === 0) {
                toast.success(`Successfully imported ${result.successCount} teachers!`);
                setTimeout(onSuccess, 1500);
            } else {
                toast.warning(
                    `Import finished. ${result.successCount} succeeded, ${result.failCount} failed.`
                );
            }
        }
    };

    const downloadTemplate = () => {
        const templateContent = "first_name,last_name,email,employee_id,specialization,qualification\nJane,Smith,jane@example.com,EMP-001,Math\\,Science,M.Sc Mathematics\n";
        const blob = new Blob([templateContent], { type: "text/csv;charset=utf-8;" });
        const link = document.createElement("a");
        const url = URL.createObjectURL(blob);
        link.setAttribute("href", url);
        link.setAttribute("download", "teacher_import_template.csv");
        link.style.visibility = "hidden";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-300">
            {!file && (
                <div
                    {...getRootProps()}
                    className={`border-2 border-dashed p-12 text-center cursor-pointer transition-all duration-500 rounded-sm bg-background/40 backdrop-blur-md group shadow-2xl ${isDragActive
                            ? "border-primary bg-primary/10 emerald-glow-sm"
                            : "border-border/60 hover:border-primary/40 hover:bg-primary/5"
                        }`}
                >
                    <input {...getInputProps()} />
                    <UploadCloud className="w-16 h-16 text-primary/40 mx-auto mb-6 group-hover:text-primary transition-colors group-hover:scale-110 duration-500" />
                    <h3 className="text-2xl font-black text-foreground uppercase tracking-widest mb-3 italic">
                        Initialize Faculty Registry Ingress
                    </h3>
                    <p className="text-[10px] text-foreground/40 font-black uppercase tracking-[0.2em] mb-8">
                        Deploy Personnel Data Payload (CSV) via Secure Gate
                    </p>
                    <div className="flex items-center justify-center gap-3 text-[9px] font-black uppercase tracking-widest text-primary/60 bg-primary/5 px-4 py-2 rounded-full w-fit mx-auto border border-primary/10">
                        <FileType className="w-4 h-4" />
                        <span>MIME-SPEC: text/csv only</span>
                    </div>
                </div>
            )}

            {!file && (
                <div className="text-center">
                    <button onClick={downloadTemplate} className="text-[10px] text-primary hover:text-primary/70 font-black uppercase tracking-widest flex items-center justify-center gap-2 mx-auto decoration-primary/30 underline underline-offset-4">
                        <Loader2 className="w-3 h-3" />
                        Faculty Protocol Template (CSV)
                    </button>
                </div>
            )}

            {file && !importResult && (
                <div className="space-y-8 p-1">
                    <div className="flex items-center gap-6 bg-primary/5 p-6 rounded-sm border border-primary/20 backdrop-blur-md shadow-2xl relative overflow-hidden group">
                        <div className="absolute right-0 top-0 h-full w-32 bg-gradient-to-l from-primary/10 to-transparent pointer-events-none" />
                        <div className="w-12 h-12 rounded-sm bg-primary/20 flex items-center justify-center shrink-0 border border-primary/30 emerald-glow-sm">
                            <FileType className="w-6 h-6 text-primary" />
                        </div>
                        <div className="flex-1 min-w-0">
                            <p className="text-xs font-black text-foreground uppercase tracking-widest truncate">
                                {file.name}
                            </p>
                            <p className="text-[9px] font-black text-primary uppercase tracking-[0.2em] mt-1 italic">
                                Faculty Payload Status: Valid ({(file.size / 1024).toFixed(1)} KB)
                            </p>
                        </div>
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => {
                                setFile(null);
                                setPreviewData([]);
                                setErrors([]);
                            }}
                            disabled={isProcessing}
                            className="text-[10px] font-black uppercase text-foreground/40 hover:text-primary transition-colors"
                        >
                            Abort
                        </Button>
                    </div>

                    {errors.length > 0 && (
                        <div className="bg-destructive/10 text-destructive p-6 rounded-sm text-[10px] space-y-3 border border-destructive/20 backdrop-blur-md">
                            <div className="font-black flex items-center gap-2 uppercase tracking-widest">
                                <AlertCircle className="w-4 h-4" /> Personnel Validation Error: Blockers Detected
                            </div>
                            <ul className="list-disc list-inside space-y-1.5 max-h-40 overflow-y-auto pl-2 font-black uppercase tracking-tight italic opacity-80">
                                {errors.map((err, i) => (
                                    <li key={i}>{err}</li>
                                ))}
                            </ul>
                        </div>
                    )}
 
                    {previewData.length > 0 && errors.length === 0 && (
                        <div className="bg-primary/10 text-primary p-6 rounded-sm text-[10px] border border-primary/20 flex items-center gap-3 font-black uppercase tracking-[0.2em] emerald-glow-sm">
                            <CheckCircle2 className="w-6 h-6 animate-pulse" />
                            Faculty Integrity Verified. Ready to synchronize {previewData.length} Personnel Nodes.
                        </div>
                    )}

                    <div className="flex justify-end gap-4 pt-8 border-t border-border/50">
                        <Button variant="ghost" onClick={onCancel} disabled={isProcessing} className="text-[10px] font-black uppercase tracking-widest text-foreground/40 hover:text-foreground">
                            Abort Operations
                        </Button>
                        <Button
                            onClick={handleImport}
                            disabled={isProcessing || errors.length > 0 || previewData.length === 0}
                            className="bg-primary text-primary-foreground rounded-sm gap-2 font-black uppercase tracking-[0.2em] text-[10px] px-10 py-6 h-auto emerald-glow shadow-2xl transition-all hover:scale-[1.02]"
                        >
                            {isProcessing ? (
                                <>
                                    <Loader2 className="w-4 h-4 animate-spin" />
                                    Synchronizing...
                                </>
                            ) : (
                                "Execute Faculty Ingress"
                            )}
                        </Button>
                    </div>
                </div>
            )}

            {importResult && (
                <div className="space-y-8 text-center py-10 animate-in zoom-in-95 duration-500">
                    <div className="w-20 h-20 bg-primary/10 rounded-sm flex items-center justify-center mx-auto mb-6 border border-primary/20 emerald-glow shadow-2xl">
                        <CheckCircle2 className="w-10 h-10 text-primary" />
                    </div>
                    <h3 className="text-3xl font-black text-foreground uppercase tracking-widest italic underline decoration-primary/30 underline-offset-8">Faculty Ingress Complete</h3>
                    <div className="flex justify-center gap-12 mt-8">
                        <div className="text-center group">
                            <div className="text-5xl font-black text-primary tracking-tighter group-hover:emerald-glow-sm transition-all">{importResult.successCount}</div>
                            <div className="text-[10px] font-black uppercase tracking-[0.3em] text-foreground/40 mt-2">Personnel Synchronized</div>
                        </div>
                        <div className="text-center group">
                            <div className="text-5xl font-black text-destructive tracking-tighter opacity-80">{importResult.failCount}</div>
                            <div className="text-[10px] font-black uppercase tracking-[0.3em] text-destructive/40 mt-2">Integrity Hazards</div>
                        </div>
                    </div>

                    {importResult.errors.length > 0 && (
                        <div className="mt-10 text-left bg-background/50 backdrop-blur-md rounded-sm p-6 border border-border/50 text-[10px] max-h-48 overflow-y-auto shadow-2xl">
                            <span className="font-black text-primary uppercase tracking-widest block mb-4 italic">Personnel Protocol Violation Log:</span>
                            <ul className="text-foreground/60 space-y-1.5 font-black uppercase tracking-tight italic pl-2 opacity-80 border-l border-primary/30">
                                {importResult.errors.map((e, i) => (
                                    <li key={i}>{e}</li>
                                ))}
                            </ul>
                        </div>
                    )}

                    <Button onClick={onSuccess} className="w-full mt-10 bg-primary text-primary-foreground rounded-sm font-black uppercase tracking-[0.3em] py-8 h-auto emerald-glow text-xs shadow-2xl hover:scale-[1.01] transition-all">
                        Terminate Session
                    </Button>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import { MoreHorizontal, Pencil, Trash2, Eye, Plus, FileUp } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Teacher } from "@/types/database";
import { deleteTeacher } from "@/app/actions/teachers";
import { toast } from "sonner";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "../ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { TeacherForm } from "./TeacherForm";
import { Card } from "@/components/ui/card";
import { BulkImportTeacherModal } from "./BulkImportTeacherModal";

interface TeacherListProps {
  initialData: Teacher[];
}

export function TeacherList({ initialData }: TeacherListProps) {
  const [data, setData] = useState<Teacher[]>(initialData);
  const [isPending, startTransition] = useTransition();
  const [isOpen, setIsOpen] = useState(false);
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [isBulkImportOpen, setIsBulkImportOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const onAdd = () => {
    setEditingTeacher(null);
    setIsOpen(true);
  };

  const onEdit = (teacher: Teacher) => {
    setEditingTeacher(teacher);
    setIsOpen(true);
  };

  const onDeleteClick = (id: string) => {
    setDeleteId(id);
    setIsDeleteDialogOpen(true);
  };

  const onDeleteConfirm = async () => {
    if (!deleteId) return;

    startTransition(async () => {
      const result = await deleteTeacher(deleteId);
      if (result.success) {
        toast.success("Teacher record deleted");
        setData((prevData) => prevData.filter((teacher) => teacher.id !== deleteId));
      } else {
        toast.error(result.error || "Failed to delete teacher");
      }
      setIsDeleteDialogOpen(false);
      setDeleteId(null);
    });
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-end gap-3">
        <Button
          onClick={() => setIsBulkImportOpen(true)}
          variant="ghost"
          className="rounded-sm border border-border bg-card/40 backdrop-blur-md font-bold gap-x-2 text-foreground/80 hover:text-primary transition-all shadow-xl"
        >
          <FileUp className="h-4 w-4" />
          Import Teachers
        </Button>
        <Button
          onClick={onAdd}
          className="rounded-sm bg-primary text-primary-foreground font-black gap-x-2 emerald-glow min-w-[180px] uppercase tracking-widest text-[10px]"
        >
          <Plus className="h-4 w-4" />
          Add Teacher
        </Button>
      </div>

      <Card className="border-border bg-card/40 backdrop-blur-xl rounded-sm overflow-hidden shadow-2xl">
        <Table>
          <TableHeader className="bg-primary/5">
            <TableRow className="border-b border-border hover:bg-transparent">
              <TableHead className="w-[180px] p-5 font-black uppercase tracking-widest text-[10px] text-primary">Employee ID</TableHead>
              <TableHead className="p-5 font-black uppercase tracking-widest text-[10px] text-primary">Teacher Name</TableHead>
              <TableHead className="p-5 font-black uppercase tracking-widest text-[10px] text-primary">Specialization</TableHead>
              <TableHead className="p-5 font-black uppercase tracking-widest text-[10px] text-primary">Status</TableHead>
              <TableHead className="text-right p-5 font-black uppercase tracking-widest text-[10px] text-primary">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {data.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={5}
                  className="h-24 text-center text-muted-foreground"
                >
                  No teachers found.
                </TableCell>
              </TableRow>
            ) : (
              data.map((teacher) => (
                <TableRow
                  key={teacher.id}
                  className="hover:bg-primary/5 transition-colors border-border/50"
                >
                  <TableCell className="p-5 font-black text-foreground transition-colors group-hover:text-primary font-mono text-xs uppercase">
                    {teacher.employee_id}
                  </TableCell>
                  <TableCell>
                    <div className="flex flex-col">
                      <span className="font-black text-foreground uppercase tracking-tight text-xs">
                        {teacher.profile?.full_name}
                      </span>
                      <span className="text-[10px] text-foreground/40 font-bold uppercase tracking-widest">
                        {teacher.profile?.email || "NO-EMAIL-NODATA"}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex flex-wrap gap-1">
                      {teacher.specialization?.map((spec) => (
                        <Badge key={spec} className="bg-primary/10 text-primary border border-primary/20 text-[9px] font-black px-2 py-0.5 rounded-sm uppercase tracking-tighter">
                          {spec}
                        </Badge>
                      ))}
                    </div>
                  </TableCell>
                  <TableCell className="p-5">
                    <Badge
                      className={cn(
                        "text-[9px] font-black px-3 py-1 rounded-sm uppercase tracking-[0.2em] shadow-lg",
                        teacher.status === "active"
                          ? "bg-primary/10 text-primary border border-primary/20 emerald-glow-sm"
                          : "bg-destructive/10 text-destructive border border-destructive/20"
                      )}
                    >
                      {teacher.status || "Operational"}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-right p-5">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" className="h-8 w-8 p-0 text-foreground/40 hover:text-primary hover:bg-primary/10 rounded-sm">
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="bg-card border-border rounded-sm shadow-2xl">
                        <DropdownMenuLabel className="text-[10px] font-black uppercase tracking-widest opacity-50 px-3">Teacher Actions</DropdownMenuLabel>
                        <DropdownMenuItem className="gap-x-2 cursor-pointer font-bold uppercase text-[10px] tracking-tight focus:bg-primary/10 focus:text-primary px-3 py-2">
                          <Eye className="h-3.5 w-3.5" /> View Profile
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => onEdit(teacher)}
                          className="gap-x-2 cursor-pointer font-bold uppercase text-[10px] tracking-tight focus:bg-primary/10 focus:text-primary px-3 py-2"
                        >
                          <Pencil className="h-3.5 w-3.5" /> Edit Teacher
                        </DropdownMenuItem>
                        <DropdownMenuSeparator className="bg-border/50" />
                        <DropdownMenuItem
                          onClick={() => onDeleteClick(teacher.id)}
                          className="gap-x-2 text-red-500 focus:text-red-600 cursor-pointer font-bold uppercase text-[10px] tracking-tight focus:bg-red-500/10 px-3 py-2"
                        >
                          <Trash2 className="h-3.5 w-3.5" /> Delete Teacher
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>

      <Dialog open={isOpen} onOpenChange={setIsOpen}>
        <DialogContent className="p-0 border-none bg-background/95 backdrop-blur-2xl max-w-xl overflow-hidden ring-1 ring-primary/20">
          <div className="bg-primary p-8 text-primary-foreground">
            <DialogHeader>
              <DialogTitle className="font-black text-2xl uppercase tracking-tighter">
                {editingTeacher ? "Edit Teacher Profile" : "Add New Teacher"}
              </DialogTitle>
              <p className="text-primary-foreground/70 text-xs font-bold uppercase tracking-widest mt-1">
                Teacher Information Setup
              </p>
            </DialogHeader>
          </div>
          <TeacherForm
            initialData={editingTeacher}
            onSuccess={() => setIsOpen(false)}
          />
        </DialogContent>
      </Dialog>

      <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <AlertDialogContent className="rounded-sm border-border bg-card/95 backdrop-blur-2xl shadow-2xl ring-1 ring-red-500/20">
          <AlertDialogHeader>
            <AlertDialogTitle className="font-black uppercase tracking-tight text-red-500 text-xl">Delete Teacher Record?</AlertDialogTitle>
            <AlertDialogDescription className="text-xs font-bold uppercase tracking-widest opacity-60">
              The teacher&apos;s record and all associated data will be permanently removed.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="rounded-sm font-black uppercase tracking-widest text-[10px] border-border bg-transparent hover:bg-foreground/5">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={onDeleteConfirm}
              className="bg-red-600 hover:bg-red-700 text-white rounded-sm font-black uppercase tracking-widest text-[10px] shadow-lg shadow-red-500/20"
            >
              {isPending ? "Deleting..." : "Confirm Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <Dialog open={isBulkImportOpen} onOpenChange={setIsBulkImportOpen}>
        <DialogContent className="sm:max-w-[600px] glass border-white/20">
          <BulkImportTeacherModal
            onSuccess={() => setIsBulkImportOpen(false)}
            onCancel={() => setIsBulkImportOpen(false)}
          />
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
    Calendar,
    Clock,
    MapPin,
    Plus,
    CheckCircle2,
    Zap,
    AlertCircle,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { createTimetableSlot } from "@/app/actions/timetable";
import { useRouter } from "next/navigation";

const WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const TIME_SLOTS = ["08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00"];
const COLORS = ["blue", "purple", "indigo", "emerald", "amber", "rose"];

interface TimetableDashboardProps {
    timetables: any[];
    classes: any[];
    subjects: any[];
    teachers: any[];
    academicYears: any[];
    userRole: string;
}

export function TimetableDashboard({ timetables, classes, subjects, teachers, academicYears, userRole }: TimetableDashboardProps) {
    const router = useRouter();
    const [selectedDay, setSelectedDay] = useState("Monday");
    const [selectedClass, setSelectedClass] = useState(classes[0]?.id || "");
    const [isAddSlotOpen, setIsAddSlotOpen] = useState(false);
    const [loading, setLoading] = useState(false);

    const currentAY = academicYears.find((ay: any) => ay.is_current) || academicYears[0];

    const [slotForm, setSlotForm] = useState({
        subject_id: "",
        teacher_id: "",
        start_time: "",
        end_time: "",
        room_number: "",
    });

    const handleCreateSlot = async () => {
        if (!selectedClass || !currentAY) return;
        setLoading(true);
        const result = await createTimetableSlot({
            class_id: selectedClass,
            academic_year_id: currentAY.id,
            day_of_week: selectedDay,
            ...slotForm,
        });
        setLoading(false);
        if (result.success) {
            setIsAddSlotOpen(false);
            setSlotForm({ subject_id: "", teacher_id: "", start_time: "", end_time: "", room_number: "" });
            router.refresh();
        }
    };

    // Filter timetable for current class and day
    const dayTimetable = timetables.find(
        (t: any) => t.class_id === selectedClass && t.day_of_week === selectedDay
    );
    const slots = dayTimetable?.slots || [];

    // Count total slots across all days
    const totalSlots = timetables
        .filter((t: any) => t.class_id === selectedClass)
        .reduce((sum: number, t: any) => sum + (t.slots?.length || 0), 0);

    return (
        <div className="space-y-12 animate-in fade-in transition-all duration-1000">
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 reveal-0">
            <div>
                <div className="flex items-center gap-x-3 mb-4">
                    <div className="px-3 py-1 rounded-sm bg-primary/10 border border-primary/20 text-[10px] font-black uppercase tracking-[0.3em] text-primary flex items-center gap-x-2">
                        <Clock className="h-3 w-3 animate-pulse" />
                        Temporal Registry Active
                    </div>
                </div>
                <h2 className="text-6xl font-black tracking-tighter text-foreground uppercase italic leading-none">
                    Temporal <span className="text-primary tracking-normal not-italic">/</span> Allocation
                </h2>
                <p className="text-foreground/50 font-black uppercase tracking-[0.25em] text-[10px] mt-4 flex items-center gap-x-3">
                    <MapPin className="h-3 w-3 text-primary" />
                    Institutional Resource Distribution Engine
                </p>
            </div>
            <div className="flex flex-wrap items-center gap-4">
                {classes.length > 0 && (
                    <div className="relative group">
                        <div className="absolute inset-0 bg-primary/5 blur-xl group-hover:bg-primary/10 transition-all" />
                        <Select value={selectedClass} onValueChange={setSelectedClass}>
                            <SelectTrigger className="w-[240px] h-14 rounded-sm border-white/10 bg-white/5 backdrop-blur-2xl font-black uppercase tracking-widest text-[11px] relative z-10 hover:border-primary/40 transition-all">
                                <SelectValue placeholder="Select Sector" />
                            </SelectTrigger>
                            <SelectContent className="glass-dark border-primary/20 p-2">
                                {classes.map((c: any) => (
                                    <SelectItem key={c.id} value={c.id} className="font-black uppercase text-[10px] tracking-widest p-3 hover:bg-primary/10 rounded-xs transition-colors cursor-pointer">
                                        {c.name}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>
                )}
                {(userRole === "admin" || userRole === "teacher") && (
                    <Dialog open={isAddSlotOpen} onOpenChange={setIsAddSlotOpen}>
                        <DialogTrigger asChild>
                            <button className="relative group px-8 h-14 bg-primary text-primary-foreground rounded-sm overflow-hidden emerald-border-glow transition-all duration-500 hover:scale-105 active:scale-95">
                                <div className="absolute inset-0 bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.2)_50%,transparent_75%)] bg-[length:250%_250%] animate-[shimmer_3s_infinite]" />
                                <div className="flex items-center gap-x-3 relative z-10 font-black text-xs uppercase tracking-[0.3em]">
                                    <Plus className="h-4 w-4" /> Initialize Node
                                </div>
                            </button>
                        </DialogTrigger>
                        <DialogContent className="p-0 border-white/10 bg-background/40 backdrop-blur-3xl max-w-xl overflow-hidden shadow-2xl rounded-sm ring-1 ring-white/10">
                            <div className="bg-primary/20 p-10 border-b border-white/10 relative overflow-hidden group">
                                <div className="absolute top-0 right-0 p-12 opacity-5 rotate-12 group-hover:rotate-45 transition-all duration-1000">
                                    <Zap className="h-32 w-32 text-primary" />
                                </div>
                                <DialogHeader className="relative z-10">
                                    <DialogTitle className="font-black text-3xl uppercase tracking-tighter italic">Temporal Command</DialogTitle>
                                    <p className="text-primary font-black uppercase tracking-[0.4em] text-[10px] mt-2 italic">Phase Initialization Interface</p>
                                </DialogHeader>
                            </div>
                            <div className="p-10 space-y-8">
                                <div className="p-6 rounded-sm bg-primary/5 border border-primary/10 flex items-start gap-x-6 relative group overflow-hidden">
                                     <div className="absolute inset-0 bg-primary text-primary-foreground opacity-0 group-hover:opacity-5 transition-opacity" />
                                    <div className="p-3 bg-primary/10 rounded-sm">
                                        <AlertCircle className="h-5 w-5 text-primary" />
                                    </div>
                                    <div className="space-y-2">
                                        <p className="text-[10px] font-black uppercase tracking-[0.4em] text-primary">Target Sector / Cycle</p>
                                        <p className="font-black text-xl text-foreground uppercase italic leading-none">
                                            {selectedDay} <span className="text-primary tracking-normal not-italic px-2">/</span> {classes.find((c: any) => c.id === selectedClass)?.name || "ΓÇö"}
                                        </p>
                                    </div>
                                </div>
                                
                                <div className="grid grid-cols-2 gap-6">
                                    <div className="space-y-3">
                                        <Label className="text-[10px] font-black uppercase tracking-[0.5em] text-foreground/40 ml-1">Curriculum Node</Label>
                                        <Select value={slotForm.subject_id} onValueChange={(v) => setSlotForm({ ...slotForm, subject_id: v })}>
                                            <SelectTrigger className="bg-white/5 border-white/10 rounded-sm h-14 font-black uppercase text-[10px] tracking-widest hover:border-primary/40 transition-all">
                                                <SelectValue placeholder="Select Subject" />
                                            </SelectTrigger>
                                            <SelectContent className="glass-dark border-primary/20">
                                                {subjects.map((s: any) => (
                                                    <SelectItem key={s.id} value={s.id} className="font-black uppercase text-[9px] tracking-widest">{s.name}</SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                    <div className="space-y-3">
                                        <Label className="text-[10px] font-black uppercase tracking-[0.5em] text-foreground/40 ml-1">Personnel ID</Label>
                                        <Select value={slotForm.teacher_id} onValueChange={(v) => setSlotForm({ ...slotForm, teacher_id: v })}>
                                            <SelectTrigger className="bg-white/5 border-white/10 rounded-sm h-14 font-black uppercase text-[10px] tracking-widest hover:border-primary/40 transition-all">
                                                <SelectValue placeholder="Select Staff" />
                                            </SelectTrigger>
                                            <SelectContent className="glass-dark border-primary/20">
                                                {teachers.map((t: any) => (
                                                    <SelectItem key={t.id} value={t.id} className="font-black uppercase text-[9px] tracking-widest">
                                                        {t.profile?.full_name}
                                                    </SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-6">
                                    <div className="space-y-3">
                                        <Label className="text-[10px] font-black uppercase tracking-[0.5em] text-foreground/40 ml-1">Activation</Label>
                                        <Input type="time" className="bg-white/5 border-white/10 rounded-sm h-14 font-black text-foreground hover:border-primary/40 transition-all px-4" value={slotForm.start_time} onChange={(e) => setSlotForm({ ...slotForm, start_time: e.target.value })} />
                                    </div>
                                    <div className="space-y-3">
                                        <Label className="text-[10px] font-black uppercase tracking-[0.5em] text-foreground/40 ml-1">Termination</Label>
                                        <Input type="time" className="bg-white/5 border-white/10 rounded-sm h-14 font-black text-foreground hover:border-primary/40 transition-all px-4" value={slotForm.end_time} onChange={(e) => setSlotForm({ ...slotForm, end_time: e.target.value })} />
                                    </div>
                                </div>

                                <div className="space-y-3">
                                    <Label className="text-[10px] font-black uppercase tracking-[0.5em] text-foreground/40 ml-1">Geospatial Coordinator</Label>
                                    <Input className="bg-white/5 border-white/10 rounded-sm h-14 font-black uppercase text-[10px] tracking-[0.2em] px-4 placeholder:text-foreground/20 hover:border-primary/40 transition-all" value={slotForm.room_number} onChange={(e) => setSlotForm({ ...slotForm, room_number: e.target.value })} placeholder="Logistics Hub / Lab 302" />
                                </div>

                                <button onClick={handleCreateSlot} disabled={loading} className="w-full relative group h-16 bg-primary text-primary-foreground rounded-sm overflow-hidden emerald-border-glow transition-all duration-500 hover:scale-[1.02] active:scale-95 disabled:opacity-50">
                                    <div className="absolute inset-0 bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.2)_50%,transparent_75%)] bg-[length:250%_250%] animate-[shimmer_3s_infinite]" />
                                    <span className="relative z-10 font-black text-[13px] uppercase tracking-[0.5em] italic">
                                        {loading ? "Initializing..." : "Commit Temporal Node"}
                                    </span>
                                </button>
                            </div>
                        </DialogContent>
                    </Dialog>
                )}
            </div>
        </div>

        <div className="grid gap-12 lg:grid-cols-4">
            {/* Day Selector */}
            <div className="lg:col-span-1 space-y-6">
                <div className="flex items-center justify-between ml-2">
                    <div className="flex items-center gap-x-3">
                        <Calendar className="h-4 w-4 text-primary animate-pulse" />
                        <h3 className="text-[11px] font-black uppercase tracking-[0.5em] text-foreground/40">Cycle Phases</h3>
                    </div>
                </div>
                <div className="glass-card p-3 space-y-2 border-white/10">
                    {WEEKDAYS.map((day) => (
                        <button
                            key={day}
                            onClick={() => setSelectedDay(day)}
                            className={`w-full group relative flex items-center justify-between p-5 rounded-sm transition-all duration-700 font-black text-[11px] uppercase tracking-[0.3em] overflow-hidden ${
                                selectedDay === day 
                                    ? "bg-primary text-primary-foreground shadow-[0_0_30px_oklch(var(--primary)/0.3)] translate-x-3 italic" 
                                    : "text-foreground/40 hover:text-foreground hover:bg-white/5"
                            }`}
                        >
                            <div className={`absolute inset-0 bg-white/10 transition-transform duration-700 ${selectedDay === day ? "translate-x-0" : "-translate-x-full group-hover:translate-x-0"}`} />
                            <span className="relative z-10">{day}</span>
                            {selectedDay === day ? (
                                <Zap className="h-4 w-4 relative z-10 animate-bounce" />
                            ) : (
                                <div className="h-1.5 w-1.5 rounded-full bg-foreground/10 group-hover:bg-primary transition-colors" />
                            )}
                        </button>
                    ))}
                </div>
            </div>

            {/* Schedule Grid */}
            <div className="lg:col-span-3 space-y-12">
                <div className="flex gap-x-10 overflow-x-auto pb-10 scrollbar-emerald">
                    {TIME_SLOTS.map((time) => {
                        const matchingSlots = slots.filter((s: any) => s.start_time?.startsWith(time));
                        return (
                            <div key={time} className="flex-1 min-w-[220px] space-y-8 animate-in slide-in-from-bottom-5 duration-700" style={{ animationDelay: `${parseInt(time) * 50}ms` }}>
                                <div className="space-y-4">
                                    <div className="flex items-center gap-x-4">
                                        <p className="text-[11px] font-black uppercase tracking-[0.6em] text-primary italic">{time}</p>
                                        <div className="h-px flex-1 bg-gradient-to-r from-primary/30 via-transparent to-transparent" />
                                    </div>
                                </div>
                                <div className="space-y-6">
                                    {matchingSlots.map((s: any) => (
                                        <div 
                                            key={s.id} 
                                            className="group relative glass-card p-6 space-y-6 transition-all duration-700 hover:emerald-border-glow hover:-translate-y-2 overflow-hidden"
                                        >
                                            <div className="absolute inset-0 bg-gradient-to-br from-primary/5 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                                            
                                            <div className="flex items-center justify-between relative z-10">
                                                <div className="flex items-center gap-x-2">
                                                    <span className="h-1.5 w-1.5 rounded-full bg-primary animate-ping" />
                                                    <span className="text-[9px] font-black uppercase tracking-[0.4em] text-primary">Node active</span>
                                                </div>
                                                <div className="p-1.5 bg-white/5 rounded-xs border border-white/10 group-hover:border-primary/40 transition-colors">
                                                    <Clock className="h-3 w-3 text-foreground/40 group-hover:text-primary transition-colors" />
                                                </div>
                                            </div>
                                            
                                            <div className="space-y-2 relative z-10">
                                                <h4 className="font-black text-foreground text-lg uppercase tracking-tighter italic leading-none group-hover:text-primary transition-colors">
                                                    {s.subject?.name || "Neural TBD"}
                                                </h4>
                                                <div className="flex items-center gap-x-2">
                                                    <div className="h-4 w-4 rounded-full bg-white/5 border border-white/10 flex items-center justify-center overflow-hidden">
                                                        <span className="text-[6px] font-black">AI</span>
                                                    </div>
                                                    <p className="text-[9px] text-foreground/40 font-black uppercase tracking-[0.2em]">
                                                        {s.teacher?.profile?.full_name}
                                                    </p>
                                                </div>
                                            </div>
                                            
                                            <div className="flex items-center justify-between pt-6 border-t border-white/5 text-[9px] font-black uppercase tracking-[0.3em] text-foreground/20 group-hover:text-foreground/60 transition-colors relative z-10">
                                                <div className="flex items-center gap-x-2">
                                                    <MapPin className="h-3.5 w-3.5 text-primary/40 group-hover:text-primary transition-all" />
                                                    {s.room_number || "Field-X"}
                                                </div>
                                                <div className="px-2 py-1 bg-white/5 rounded-xs border border-white/10 group-hover:text-primary group-hover:border-primary/20">
                                                    {s.end_time?.slice(0, 5)}
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                    {matchingSlots.length === 0 && (userRole === "admin" || userRole === "teacher") && (
                                        <button 
                                            onClick={() => { 
                                                setSlotForm({ 
                                                    ...slotForm, 
                                                    start_time: time, 
                                                    end_time: `${String(parseInt(time) + 1).padStart(2, "0")}:00` 
                                                }); 
                                                setIsAddSlotOpen(true); 
                                            }}
                                            className="h-40 w-full rounded-sm border-2 border-dashed border-white/5 bg-white/[0.01] flex flex-col items-center justify-center group hover:border-primary/40 hover:bg-primary/[0.03] transition-all duration-700 relative overflow-hidden"
                                        >
                                            <div className="absolute inset-0 bg-primary/5 opacity-0 group-hover:opacity-100 transition-opacity" />
                                            <Plus className="h-6 w-6 text-foreground/10 group-hover:text-primary group-hover:scale-125 transition-all duration-700 relative z-10" />
                                            <span className="mt-4 text-[9px] font-black uppercase tracking-[0.5em] text-foreground/0 group-hover:text-primary group-hover:translate-y-0 translate-y-2 opacity-0 group-hover:opacity-60 transition-all duration-500 relative z-10">Initialize</span>
                                        </button>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="grid gap-10 md:grid-cols-2">
                    <div className="group relative glass-card p-10 space-y-8 transition-all duration-700 hover:emerald-border-glow overflow-hidden">
                        <div className="absolute top-0 right-0 p-12 opacity-[0.03] rotate-12 group-hover:rotate-0 transition-transform duration-1000">
                             <CheckCircle2 className="h-48 w-48 text-primary" />
                        </div>
                        <div className="flex items-center justify-between relative z-10">
                            <div className="space-y-3">
                                <p className="text-[10px] font-black uppercase tracking-[0.5em] text-primary">Structural Integrity</p>
                                <div className="flex items-center gap-x-4">
                                    <h4 className="text-6xl font-black text-foreground italic leading-none">100</h4>
                                    <div className="px-2 py-1 bg-primary/20 border border-primary/20 rounded-xs text-primary font-black text-[10px] uppercase">Optimal</div>
                                </div>
                            </div>
                        </div>
                        <p className="text-[10px] font-black uppercase tracking-[0.4em] text-foreground/30 leading-relaxed max-w-[280px] relative z-10 italic">
                            Temporal resource alignment verification complete. Zero collision probability detected.
                        </p>
                    </div>
                    
                    <div className="group relative glass-card p-10 space-y-8 transition-all duration-700 hover:emerald-border-glow overflow-hidden">
                        <div className="absolute top-0 right-0 p-12 opacity-[0.03] rotate-12 group-hover:rotate-0 transition-transform duration-1000">
                             <Zap className="h-48 w-48 text-primary" />
                        </div>
                        <div className="flex items-center justify-between relative z-10">
                            <div className="space-y-3">
                                <p className="text-[10px] font-black uppercase tracking-[0.5em] text-primary">Node Saturation</p>
                                <h4 className="text-6xl font-black text-foreground italic leading-none">{totalSlots}</h4>
                            </div>
                        </div>
                        <p className="text-[10px] font-black uppercase tracking-[0.4em] text-foreground/30 leading-relaxed max-w-[280px] relative z-10 italic">
