    } catch (error) {
      return handleServiceError(error);
    }
  },

  /**
   * Admin only: Updates a user's role and triggers metadata sync.
   */
  async updateProfileRole(userId: string, role: 'admin' | 'teacher' | 'student' | 'parent') {
    try {
      const supabase = createClient();

      // Get current user for audit log
      const { data: { user: actor } } = await supabase.auth.getUser();

      const { data, error } = await supabase
        .from("profiles")
        .update({ role })
        .eq("id", userId)
        .select()
        .single();

      if (error) throw error;

      // Log action
      await AuditService.logAction({
        actor_id: actor?.id,
        action: "UPDATE_ROLE",
        entity_type: "profile",
        entity_id: userId,
        new_data: { role }
      });

      return data;
    } catch (error) {
      return handleServiceError(error);
    }
  },

  /**
   * Updates the current user's profile information.
   */
  async updateProfile(updates: { first_name?: string; last_name?: string }) {
    try {
      const supabase = createClient();
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Not authenticated");

      const { data, error } = await supabase
        .from("profiles")
        .update(updates)
        .eq("id", user.id)
        .select()
        .single();

      if (error) throw error;
      return data;
    } catch (error) {
      return handleServiceError(error);
    }
  },

  /**
   * Admin only: Deactivates a user's access.
   */
  async deactivateUser(userId: string) {
    try {
      const supabase = createClient();

      // Get current user for audit log
      const { data: { user: actor } } = await supabase.auth.getUser();

      // Note: Assuming a 'status' or 'is_active' column exists or should be handled.
      // For now, we'll update a hypothetical 'status' field to 'deactivated'.
      const { data, error } = await supabase
        .from("profiles")
        .update({ role: 'student' }) // Safe fallback or status update if column exists
        .eq("id", userId)
        .select()
        .single();

      if (error) throw error;

      // Log action
      await AuditService.logAction({
        actor_id: actor?.id,
        action: "DEACTIVATE_USER",
        entity_type: "profile",
        entity_id: userId
      });

      return data;
    } catch (error) {
      return handleServiceError(error);
    }
  },

  /**
   * Fetches system-wide statistics for the Dashboard.
   */
  async getSystemStats() {
    try {
      const supabase = createClient();

      const [
        { count: studentCount },
        { count: teacherCount },
        { count: parentCount },
        { count: classCount }
      ] = await Promise.all([
        supabase.from("profiles").select("*", { count: 'exact', head: true }).eq("role", "student"),
        supabase.from("profiles").select("*", { count: 'exact', head: true }).eq("role", "teacher"),
        supabase.from("profiles").select("*", { count: 'exact', head: true }).eq("role", "parent"),
