"use client"

import { useState, useEffect } from 'react';

export interface TelemetryData {
  latitude: number;
  longitude: number;
  speed: string;
  status: 'moving' | 'stopped' | 'alert';
  heading: number;
}

// Initial positions for school buses
const BUS_ROUTES = [
  { id: 'R10', start: { lat: 25.276985, lng: 55.296249 }, heading: 45 },
  { id: 'R04', start: { lat: 25.285000, lng: 55.305000 }, heading: 120 },
  { id: 'S-XX', start: { lat: 25.270000, lng: 55.280000 }, heading: 300, status: 'alert' as const },
];

export function useTelemetry(routeId: string) {
  const [data, setData] = useState<TelemetryData | null>(null);

  useEffect(() => {
    const route = BUS_ROUTES.find(r => r.id === routeId);
    if (!route) return;

    // Initialize position
    let currentLat = route.start.lat;
    let currentLng = route.start.lng;
    let currentHeading = route.heading;

    const interval = setInterval(() => {
      // Small random movement simulation
      if (route.status !== 'alert') {
        const delta = 0.00005;
        currentLat += (Math.random() - 0.5) * delta;
        currentLng += (Math.random() - 0.5) * delta;
        currentHeading += (Math.random() - 0.5) * 5;
      }

      setData({
        latitude: currentLat,
        longitude: currentLng,
        speed: route.status === 'alert' ? '0 km/h' : `${Math.floor(Math.random() * 10) + 35} km/h`,
        status: (route.status as any) || 'moving',
        heading: currentHeading,
      });
    }, 2000);

    return () => clearInterval(interval);
  }, [routeId]);

  return data;
}

export function useAIPerformanceSim() {
  const [score, setScore] = useState(86.4);
  const [trend, setTrend] = useState(4.2);

  useEffect(() => {
    const interval = setInterval(() => {
      // Simulate slow neural calculation changes
      setScore(prev => +(prev + (Math.random() - 0.5) * 0.1).toFixed(1));
      setTrend(prev => +(prev + (Math.random() - 0.5) * 0.05).toFixed(2));
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  return { score, trend };
}

import { createClient } from '@/utils/supabase/middleware'
import { NextResponse, type NextRequest } from 'next/server'

export async function updateSession(request: NextRequest) {
  const { supabase, supabaseResponse } = createClient(request)

  // IMPORTANT: Avoid writing any logic between createServerClient and
  // getUser(). A simple mistake can make it very hard to debug
  // issues with sessions being lost.

  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (
    !user &&
    !request.nextUrl.pathname.startsWith('/login') &&
    !request.nextUrl.pathname.startsWith('/auth')
  ) {
    // no user, potentially respond by redirecting the user to the login page
    const url = request.nextUrl.clone()
    url.pathname = '/login'
    return NextResponse.redirect(url)
  }

  // Role-based access control & Impersonation Handling
  if (user) {
    const cookieStore = request.cookies;
    const impersonationId = cookieStore.get("impersonation_user_id")?.value;

    // Fetch REAL profile role directly from DB for security
    const { data: realProfile } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .single();

    const realRole = realProfile?.role;
    let effectiveRole = realRole;
    let effectiveUserId = user.id;

    // Security check for impersonation
    if (impersonationId) {
        if (realRole !== 'admin') {
            // Non-admin trying to impersonate? Clear it immediately.
            const response = NextResponse.redirect(new URL(request.url))
            response.cookies.delete("impersonation_user_id")
            return response
        }

        // Fetch the target user's role
        const { data: targetProfile } = await supabase
          .from("profiles")
          .select("role")
          .eq("id", impersonationId)
          .single();
        
        if (targetProfile) {
            effectiveRole = targetProfile.role;
            effectiveUserId = impersonationId;
        }
    }

    const path = request.nextUrl.pathname

    // Define role-to-path mapping
    const rolePaths: Record<string, string> = {
      admin: '/admin',
      teacher: '/teacher',
      student: '/student',
      parent: '/parent'
    };

    // Check if the current path starts with a role-restricted prefix
    const restrictedPrefixes = Object.values(rolePaths);
    const targetPrefix = restrictedPrefixes.find(p => path.startsWith(p));

    if (targetPrefix) {
        // Find which role is allowed for this prefix
        const allowedRole = Object.keys(rolePaths).find(k => rolePaths[k] === targetPrefix);
        
        // Admins can ALWAYS access admin routes, even when impersonating (it switches context)
        // However, if they are impersonating a student, they should be able to access /student routes
        if (effectiveRole !== allowedRole && realRole !== 'admin') {
            return NextResponse.redirect(new URL('/unauthorized', request.url))
        }
    }
  }

  // IMPORTANT: You *must* return the supabaseResponse object as it is. If you're
  // creating a new response object with NextResponse.next() make sure to:
  // 1. Pass the request in it, like so:
  //    const myNewResponse = NextResponse.next({ request })
  // 2. Copy over the cookies, like so:
  //    myNewResponse.cookies.setAll(supabaseResponse.cookies.getAll())
  // 3. Change the myNewResponse object to fit your needs, but remember that it's a NEW object!

  return supabaseResponse
}

